insert into _new (name, file, body_part, en, es) values
  ('Fondos de Pecho en Torre de Dominadas', 'chest-dip-on-dip-pull-up-cage.gif', 'chest', '["Adjust the dip bars to a height that allows you to comfortably grip them.", "Stand between the bars and place your hands on each bar, slightly wider than shoulder-width apart.", "Jump up and straighten your arms, supporting your body weight on the bars.", "Bend your knees and cross your ankles behind you.", "Lower your body by bending your elbows, keeping your chest up and your shoulders down.", "Continue lowering until your shoulders are below your elbows or until you feel a stretch in your chest.", "Push through your palms and extend your elbows to raise your body back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta las barras de fondos a una altura que te permita agarrarlas cómodamente.", "Ponte de pie entre las barras y coloca las manos en cada barra, un poco más separadas que el ancho de los hombros.", "Salta y estira los brazos, sosteniendo el peso de tu cuerpo sobre las barras.", "Flexiona las rodillas y cruza los tobillos detrás de ti.", "Baja el cuerpo flexionando los codos, manteniendo el pecho elevado y los hombros bajos.", "Continúa bajando hasta que los hombros queden por debajo de los codos o hasta que sientas un estiramiento en el pecho.", "Empuja con las palmas y extiende los codos para subir el cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Fondos en Barra Recta con Lastre', 'weighted-straight-bar-dip.gif', 'chest', '["Position yourself between parallel bars with your arms fully extended and your body straight.", "Lower your body by bending your elbows until your upper arms are parallel to the ground.", "Pause for a moment, then push yourself back up to the starting position by straightening your arms.", "Repeat for the desired number of repetitions."]', '["Colócate entre las barras paralelas con los brazos completamente extendidos y el cuerpo recto.", "Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.", "Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Limpiaparabrisas Isométrico (Flexión)', 'isometric-wipers.gif', 'chest', '["Start by lying flat on your back on a mat or bench.", "Extend your arms straight out to the sides, perpendicular to your body.", "Engage your core and lift both legs off the ground, keeping them together and straight.", "Slowly lower your legs to one side, aiming to touch the ground with your feet while maintaining control.", "Pause for a moment, then use your core to lift your legs back to the starting position.", "Repeat the movement, this time lowering your legs to the opposite side.", "Continue alternating sides for the desired number of repetitions."]', '["Comienza acostado boca arriba en una esterilla o un banco.", "Extiende los brazos hacia los lados, perpendiculares al cuerpo.", "Activa el core y levanta ambas piernas del suelo, manteniéndolas juntas y rectas.", "Baja lentamente las piernas hacia un lado, intentando tocar el suelo con los pies mientras mantienes el control.", "Haz una pausa breve, luego usa el core para llevar las piernas de vuelta a la posición inicial.", "Repite el movimiento, esta vez bajando las piernas hacia el lado opuesto.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Movilidad de Hombro Sentado a 1 Pierna con Rodillo', 'roller-seated-single-leg-shoulder-flexor-depresor-retractor.gif', 'chest', '["Sit on a flat surface with your legs extended in front of you.", "Hold the roller with both hands, palms facing down, and place it on your thighs.", "Lean back slightly and engage your core muscles.", "Raise the roller up to shoulder level, keeping your arms straight.", "Slowly lower the roller back down to your thighs.", "Repeat for the desired number of repetitions."]', '["Siéntate sobre una superficie plana con las piernas extendidas frente a ti.", "Sostén el rodillo con ambas manos, con las palmas hacia abajo, y colócalo sobre tus muslos.", "Inclínate ligeramente hacia atrás y contrae los músculos del core.", "Eleva el rodillo hasta la altura de los hombros, manteniendo los brazos rectos.", "Baja lentamente el rodillo de nuevo hacia los muslos.", "Repite el número de repeticiones deseado."]'),
  ('Movilidad de Hombro Sentado con Rodillo', 'roller-seated-shoulder-flexor-depresor-retractor.gif', 'chest', '["Sit on a flat surface with your legs extended in front of you.", "Hold the roller with both hands, palms facing down, and place it on your thighs.", "Lean forward slightly and roll the roller away from your body, extending your arms straight in front of you.", "Pause for a moment, then slowly roll the roller back towards your body, bending your arms and bringing the roller back to your thighs.", "Repeat for the desired number of repetitions."]', '["Siéntate sobre una superficie plana con las piernas extendidas frente a ti.", "Sostén el rodillo con ambas manos, con las palmas hacia abajo, y colócalo sobre tus muslos.", "Inclínate ligeramente hacia delante y aleja el rodillo de tu cuerpo, extendiendo los brazos rectos frente a ti.", "Haz una pausa por un momento, luego rueda el rodillo lentamente de vuelta hacia tu cuerpo, doblando los brazos y trayéndolo de nuevo hacia los muslos.", "Repite el número de repeticiones deseado."]'),
  ('Pase de Pecho con Balón Medicinal', 'medicine-ball-chest-pass.gif', 'chest', '["Stand with your feet shoulder-width apart, holding the medicine ball at chest level.", "Extend your arms forward, pushing the medicine ball away from your chest with force.", "As you release the ball, follow through with your arms and torso, transferring your weight from your back foot to your front foot.", "Catch the ball as it rebounds off the wall or partner, and immediately repeat the movement.", "Continue for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo el balón medicinal a la altura del pecho.", "Extiende los brazos hacia adelante, empujando el balón medicinal con fuerza para alejarlo del pecho.", "Al soltar el balón, continúa el movimiento con los brazos y el torso, transfiriendo el peso del pie de atrás al pie de adelante.", "Atrapa el balón cuando rebote en la pared o en tu compañero, y repite el movimiento de inmediato.", "Continúa durante el número de repeticiones deseado."]'),
  ('Press a 1 Brazo con Mancuerna sobre Fitball', 'dumbbell-one-arm-press-on-exercise-ball.gif', 'chest', '["Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.", "Hold a dumbbell in one hand and position it at shoulder height, with your elbow bent and palm facing forward.", "Slowly press the dumbbell upward until your arm is fully extended, while keeping your core engaged and maintaining balance on the exercise ball.", "Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."]', '["Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y las rodillas flexionadas en un ángulo de 90 grados.", "Sostén una mancuerna en una mano y colócala a la altura del hombro, con el codo flexionado y la palma hacia adelante.", "Empuja lentamente la mancuerna hacia arriba hasta que el brazo quede completamente extendido, manteniendo el core activado y el equilibrio sobre el balón de estabilidad.", "Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia al otro brazo."]'),
  ('Press a 1 Brazo con Mancuerna y Agarre Supino', 'dumbbell-one-arm-reverse-grip-press.gif', 'chest', '["Sit on a flat bench with a dumbbell in one hand, palm facing towards your body.", "Place your feet flat on the ground and keep your back straight.", "Raise the dumbbell to shoulder height, keeping your elbow close to your body.", "Press the dumbbell upwards until your arm is fully extended.", "Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."]', '["Siéntate en un banco plano con una mancuerna en una mano, con la palma hacia el cuerpo.", "Coloca los pies planos sobre el suelo y mantén la espalda recta.", "Levanta la mancuerna hasta la altura del hombro, manteniendo el codo cerca del cuerpo.", "Empuja la mancuerna hacia arriba hasta que el brazo quede completamente extendido.", "Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia al otro brazo."]'),
  ('Press a 1 Brazo en el Suelo con Kettlebell de Rango Extendido', 'kettlebell-extended-range-one-arm-press-on-floor.gif', 'chest', '["Start by lying on your back on the floor with your knees bent and feet flat on the ground.", "Hold a kettlebell in one hand, with your palm facing towards your feet.", "Extend your arm straight up towards the ceiling, keeping your elbow locked and your wrist straight.", "Slowly lower the kettlebell back down to the starting position, maintaining control throughout the movement.", "Repeat for the desired number of repetitions, then switch to the other arm."]', '["Comienza acostado boca arriba en el suelo con las rodillas dobladas y los pies planos sobre el suelo.", "Sujeta una pesa rusa con una mano, con la palma hacia los pies.", "Extiende el brazo recto hacia el techo, manteniendo el codo bloqueado y la muñeca recta.", "Baja lentamente la pesa rusa de vuelta a la posición inicial, manteniendo el control durante todo el movimiento.", "Repite el número de repeticiones deseado, luego cambia al otro brazo."]'),
  ('Press a 1 Brazo en Polea sobre Fitball', 'cable-one-arm-press-on-exercise-ball.gif', 'chest', '["Sit on an exercise ball with your feet flat on the ground and your back straight.", "Hold a cable handle in one hand and position your arm at chest height, elbow bent.", "Place your other hand on your hip for stability.", "Press the cable handle forward, extending your arm fully.", "Pause for a moment, then slowly return to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.", "Sujeta una agarradera del cable con una mano y coloca el brazo a la altura del pecho, con el codo flexionado.", "Coloca la otra mano en la cadera para mantener el equilibrio.", "Empuja la agarradera del cable hacia adelante, extendiendo el brazo por completo.", "Haz una pausa por un momento, luego regresa lentamente a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Press Alterno en el Suelo con Kettlebells', 'kettlebell-alternating-press-on-floor.gif', 'chest', '["Start by lying on your back on the floor with your knees bent and feet flat on the ground.", "Hold a kettlebell in each hand, with your palms facing towards your feet and your arms extended straight up towards the ceiling.", "Lower one kettlebell down towards your shoulder while keeping the other kettlebell extended straight up.", "Press the lowered kettlebell back up to the starting position while simultaneously lowering the other kettlebell down towards your shoulder.", "Continue alternating the press motion with each kettlebell for the desired number of repetitions."]', '["Comienza acostado boca arriba en el suelo con las rodillas dobladas y los pies planos sobre el suelo.", "Sostén una pesa rusa en cada mano, con las palmas hacia los pies y los brazos extendidos rectos hacia el techo.", "Baja una pesa rusa hacia el hombro mientras mantienes la otra pesa rusa extendida recta hacia arriba.", "Empuja la pesa rusa bajada de vuelta hacia la posición inicial mientras al mismo tiempo bajas la otra pesa rusa hacia el hombro.", "Continúa alternando el movimiento de empuje con cada pesa rusa durante el número de repeticiones deseado."]'),
  ('Press con Mancuernas sobre Fitball', 'dumbbell-press-on-exercise-ball.gif', 'chest', '["Sit on an exercise ball with your feet flat on the ground and dumbbells in each hand, resting on your thighs.", "Slowly walk your feet forward, rolling the exercise ball until your lower back is supported on the ball and your knees are at a 90-degree angle.", "Raise the dumbbells to shoulder height, palms facing forward.", "Press the dumbbells upward until your arms are fully extended.", "Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate sobre un balón de estabilidad con los pies planos en el suelo y una mancuerna en cada mano, apoyadas sobre los muslos.", "Camina lentamente hacia adelante con los pies, haciendo rodar el balón de estabilidad hasta que tu zona lumbar quede apoyada sobre el balón y tus rodillas formen un ángulo de 90 grados.", "Sube las mancuernas hasta la altura de los hombros, con las palmas hacia adelante.", "Empuja las mancuernas hacia arriba hasta que los brazos estén completamente extendidos.", "Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Press de Banca con Banda Elástica', 'band-bench-press.gif', 'chest', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.", "Grasp the band handles with an overhand grip, slightly wider than shoulder-width apart.", "Extend your arms fully, pushing the bands away from your chest.", "Slowly lower the bands back down to your chest, keeping your elbows at a 90-degree angle.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.", "Agarra las agarraderas de la banda con un agarre prono, un poco más separadas que el ancho de los hombros.", "Extiende los brazos por completo, empujando las bandas alejándolas del pecho.", "Baja lentamente las bandas de vuelta hacia el pecho, manteniendo los codos en un ángulo de 90 grados.", "Repite el número de repeticiones deseado."]'),
  ('Press de Banca con Barra y Agarre Supino Abierto', 'barbell-wide-reverse-grip-bench-press.gif', 'chest', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.", "Grasp the barbell with a wide reverse grip, slightly wider than shoulder-width apart.", "Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.", "Lower the barbell slowly towards your chest, keeping your elbows tucked in and your wrists straight.", "Pause for a moment when the barbell touches your chest, then push it back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.", "Sujeta la barra con un agarre supino amplio, un poco más separado que el ancho de los hombros.", "Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos.", "Baja la barra lentamente hacia el pecho, manteniendo los codos pegados al cuerpo y las muñecas rectas.", "Haz una pausa breve cuando la barra toque el pecho y luego empújala de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Press de Banca con Mancuernas', 'dumbbell-bench-press-0289.gif', 'chest', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.", "Hold a dumbbell in each hand, with your palms facing forward and your arms extended above your chest.", "Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle.", "Pause for a moment, then push the dumbbells back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.", "Sujeta una mancuerna en cada mano, con las palmas hacia adelante y los brazos extendidos por encima del pecho.", "Baja lentamente las mancuernas hacia los lados del pecho, manteniendo los codos en un ángulo de 90 grados.", "Haz una pausa breve, luego empuja las mancuernas de vuelta hacia arriba hasta la posición inicial, extendiendo completamente los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Press de Banca con Mancuernas y Agarre Supino', 'dumbbell-reverse-bench-press.gif', 'chest', '["Lie flat on a bench with your feet flat on the ground and your knees bent.", "Hold a dumbbell in each hand with an overhand grip, palms facing towards your feet.", "Extend your arms straight up towards the ceiling, keeping a slight bend in your elbows.", "Slowly lower the dumbbells towards your chest, allowing your elbows to flare out to the sides.", "Pause for a moment at the bottom, then push the dumbbells back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca arriba en un banco con los pies apoyados en el suelo y las rodillas flexionadas.", "Sujeta una mancuerna en cada mano con agarre prono, con las palmas hacia tus pies.", "Extiende los brazos rectos hacia el techo, manteniendo una ligera flexión en los codos.", "Baja lentamente las mancuernas hacia el pecho, permitiendo que los codos se abran hacia los lados.", "Haz una pausa por un momento en la parte inferior, luego empuja las mancuernas de nuevo hacia arriba hasta la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Press de Banca en Máquina Smith con Agarre Abierto', 'smith-wide-grip-bench-press.gif', 'chest', '["Adjust the bench to a comfortable position on the smith machine.", "Lie down on the bench with your feet flat on the ground.", "Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.", "Unrack the barbell and lower it slowly towards your chest, keeping your elbows out to the sides.", "Pause for a moment when the barbell touches your chest.", "Push the barbell back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', '["Ajusta el banco a una posición cómoda en la máquina Smith.", "Túmbate en el banco con los pies planos sobre el suelo.", "Agarra la barra con un agarre amplio, un poco más ancho que la separación de los hombros.", "Desengancha la barra y bájala lentamente hacia tu pecho, manteniendo los codos hacia afuera a los costados.", "Haz una pausa breve cuando la barra toque el pecho.", "Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Press de Banca en Máquina Smith con Agarre Supino', 'smith-reverse-grip-press.gif', 'chest', '["Adjust the height of the smith machine bar to chest level.", "Stand facing the bar with your feet shoulder-width apart.", "Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.", "Step back and position yourself with a slight bend in your knees.", "Keep your chest up and core engaged throughout the exercise.", "Lower the bar towards your chest, keeping your elbows tucked in.", "Pause for a moment at the bottom, then push the bar back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura de la barra de la máquina Smith a la altura del pecho.", "Ponte de pie frente a la barra con los pies separados a la altura de los hombros.", "Sujeta la barra con un agarre prono, con las manos un poco más separadas que el ancho de los hombros.", "Da un paso atrás y colócate con una ligera flexión en las rodillas.", "Mantén el pecho elevado y el core activado durante todo el ejercicio.", "Baja la barra hacia el pecho, manteniendo los codos pegados al cuerpo.", "Haz una pausa por un momento en la posición baja, luego empuja la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Press de Banca en Polea', 'cable-bench-press.gif', 'chest', '["Adjust the cable machine to chest height and attach the handles.", "Stand facing away from the machine with your feet shoulder-width apart.", "Grasp the handles with an overhand grip and step forward to create tension in the cables.", "Position your feet firmly on the ground and engage your core.", "Bend your elbows and bring your hands to shoulder level, keeping your elbows at a 90-degree angle.", "Push the handles forward, extending your arms fully in front of you.", "Pause for a moment, then slowly reverse the movement, bringing your hands back to shoulder level.", "Repeat for the desired number of repetitions."]', '["Ajusta la máquina de cable a la altura del pecho y coloca las agarraderas.", "Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros.", "Sujeta las agarraderas con agarre prono y da un paso hacia adelante para crear tensión en los cables.", "Coloca los pies firmemente en el suelo y activa el core.", "Flexiona los codos y lleva las manos a la altura de los hombros, manteniendo los codos en un ángulo de 90 grados.", "Empuja las agarraderas hacia adelante, extendiendo completamente los brazos frente a ti.", "Haz una pausa breve, luego invierte lentamente el movimiento, llevando las manos de vuelta a la altura de los hombros.", "Repite el número de repeticiones deseado."]'),
  ('Press de Pecho a 1 Brazo con Giro con Banda Elástica', 'band-one-arm-twisting-chest-press.gif', 'chest', '["Attach the band to a sturdy anchor point at chest height.", "Stand with your side facing the anchor point and grab the band with one hand.", "Step away from the anchor point to create tension in the band.", "Position your feet shoulder-width apart and slightly bend your knees.", "Bring your hand holding the band across your body, towards the opposite shoulder.", "While maintaining tension in the band, push your hand forward and away from your body, extending your arm.", "Slowly return to the starting position and repeat for the desired number of repetitions.", "Switch sides and repeat the exercise with the other hand."]', '["Sujeta la banda a un punto de anclaje resistente a la altura del pecho.", "Ponte de pie con el costado hacia el punto de anclaje y agarra la banda con una mano.", "Aléjate del punto de anclaje para generar tensión en la banda.", "Coloca los pies separados a la altura de los hombros y flexiona ligeramente las rodillas.", "Lleva la mano que sostiene la banda a través del cuerpo, hacia el hombro opuesto.", "Manteniendo la tensión en la banda, empuja la mano hacia adelante y alejándola del cuerpo, extendiendo el brazo.", "Regresa lentamente a la posición inicial y repite el número de repeticiones deseado.", "Cambia de lado y repite el ejercicio con la otra mano."]'),
  ('Press de Pecho Cerrado en Máquina', 'machine-inner-chest-press.gif', 'chest', '["Adjust the seat height and position yourself on the machine with your back flat against the pad.", "Grasp the handles with an overhand grip and position your elbows at a 90-degree angle.", "Push the handles forward until your arms are fully extended, exhaling during the movement.", "Pause for a moment at the end of the movement, then slowly return to the starting position, inhaling as you do so.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura del asiento y colócate en la máquina con la espalda totalmente apoyada en la almohadilla.", "Sujeta las asas con un agarre prono y coloca los codos en un ángulo de 90 grados.", "Empuja las asas hacia adelante hasta que los brazos queden completamente extendidos, exhalando durante el movimiento.", "Haz una pausa al final del movimiento y luego vuelve lentamente a la posición inicial, inhalando mientras lo haces.", "Repite el número de repeticiones deseado."]'),
  ('Press de Pecho de Pie en Máquina', 'lever-standing-chest-press.gif', 'chest', '["Adjust the seat height and position yourself on the machine with your feet flat on the ground.", "Grasp the handles with an overhand grip and position your hands at chest level.", "Push the handles forward until your arms are fully extended, keeping your elbows slightly bent.", "Pause for a moment, then slowly bring the handles back towards your chest, maintaining control throughout the movement.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura del asiento y colócate en la máquina con los pies planos en el suelo.", "Agarra las asas con un agarre prono y coloca las manos a la altura del pecho.", "Empuja las asas hacia adelante hasta que los brazos queden completamente extendidos, manteniendo los codos ligeramente flexionados.", "Haz una pausa por un momento y luego lleva lentamente las asas de vuelta hacia el pecho, manteniendo el control durante todo el movimiento.", "Repite el número de repeticiones deseado."]'),
  ('Press de Pecho en Máquina', 'lever-chest-press.gif', 'chest', '["Adjust the seat height and position yourself on the machine with your back flat against the pad.", "Grasp the handles with an overhand grip and position your elbows at a 90-degree angle.", "Push the handles forward until your arms are fully extended, exhaling during the movement.", "Pause briefly at the end of the movement, then slowly return to the starting position, inhaling as you do so.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura del asiento y colócate en la máquina con la espalda totalmente apoyada en la almohadilla.", "Sujeta las asas con un agarre prono y coloca los codos en un ángulo de 90 grados.", "Empuja las asas hacia adelante hasta que los brazos queden completamente extendidos, exhalando durante el movimiento.", "Haz una pausa breve al final del movimiento, luego vuelve lentamente a la posición inicial, inhalando mientras lo haces.", "Repite el número de repeticiones deseado."]'),
  ('Press de Pecho en Polea sobre Fitball', 'cable-press-on-exercise-ball.gif', 'chest', '["Sit on an exercise ball with your feet flat on the ground and your knees at a 90-degree angle.", "Hold the cable handles at chest height with your palms facing down and your elbows bent.", "Engage your core and press the cable handles forward until your arms are fully extended.", "Pause for a moment, then slowly release the tension and bring the cable handles back to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y las rodillas en un ángulo de 90 grados.", "Sujeta las agarraderas del cable a la altura del pecho con las palmas hacia abajo y los codos flexionados.", "Activa el core y empuja las agarraderas del cable hacia adelante hasta que los brazos queden completamente extendidos.", "Haz una pausa por un momento y luego libera lentamente la tensión, regresando las agarraderas del cable a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Press de Pecho Sentado con Banda Elástica', 'resistance-band-seated-chest-press.gif', 'chest', '["Sit on a chair or bench with your back straight and feet flat on the ground.", "Hold the resistance band handles in each hand, with your palms facing down and elbows bent at a 90-degree angle.", "Extend your arms forward, pushing the resistance band away from your chest.", "Pause for a moment at the end of the movement, then slowly return to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en una silla o banco con la espalda recta y los pies apoyados en el suelo.", "Sostén las asas de la banda elástica en cada mano, con las palmas hacia abajo y los codos flexionados en un ángulo de 90 grados.", "Extiende los brazos hacia adelante, alejando la banda elástica de tu pecho.", "Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Press de Pecho Sentado en Polea', 'cable-seated-chest-press.gif', 'chest', '["Adjust the seat height and cable handles to a comfortable position.", "Sit on the bench with your back straight and feet flat on the floor.", "Grasp the cable handles with an overhand grip at shoulder height.", "Push the handles forward and away from your body, extending your arms fully.", "Pause for a moment, then slowly bring the handles back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura del asiento y las agarraderas del cable a una posición cómoda.", "Siéntate en el banco con la espalda recta y los pies apoyados planos en el suelo.", "Sujeta las agarraderas del cable con un agarre prono a la altura del hombro.", "Empuja las agarraderas hacia adelante y alejándolas del cuerpo, extendiendo los brazos por completo.", "Haz una pausa por un momento y luego regresa lentamente las agarraderas a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Press Declinado a 1 Brazo con Mancuerna', 'dumbbell-one-arm-decline-chest-press.gif', 'chest', '["Lie on a decline bench with a dumbbell in one hand, resting on your chest.", "Place your feet flat on the ground and keep your back pressed against the bench.", "Extend your arm and push the dumbbell up towards the ceiling, fully extending your elbow.", "Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."]', '["Túmbate en un banco declinado con una mancuerna en una mano, apoyada sobre el pecho.", "Coloca los pies planos sobre el suelo y mantén la espalda presionada contra el banco.", "Extiende el brazo y empuja la mancuerna hacia el techo, extendiendo completamente el codo.", "Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia al otro brazo."]'),
  ('Press Declinado a 1 Brazo en Polea', 'cable-decline-one-arm-press.gif', 'chest', '["Adjust the cable machine to a decline position.", "Stand facing away from the machine and grab the handle with one hand.", "Position yourself with your back against the decline bench and your arm extended straight in front of you.", "Bend your elbow and lower the handle towards your chest while keeping your upper arm stationary.", "Pause for a moment at the bottom, then push the handle back up to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Ajusta la máquina de cable a una posición declinada.", "Ponte de pie de espaldas a la máquina y sujeta la agarradera con una mano.", "Colócate con la espalda contra el banco declinado y el brazo extendido recto frente a ti.", "Flexiona el codo y baja la agarradera hacia el pecho, manteniendo el brazo superior quieto.", "Haz una pausa breve en la parte más baja, luego empuja la agarradera de vuelta hacia la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Press Declinado Cerrado en Máquina Smith con Agarre Supino', 'smith-machine-reverse-decline-close-grip-bench-press.gif', 'chest', '["Adjust the smith machine to a decline position.", "Lie down on the bench with your feet secured under the foot pads.", "Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.", "Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.", "Pause for a moment at the bottom, then push the barbell back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la máquina Smith a una posición declinada.", "Túmbate en el banco con los pies asegurados bajo las almohadillas para los pies.", "Agarra la barra con un agarre cerrado, un poco más estrecho que el ancho de los hombros.", "Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo.", "Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Press Declinado con Barra y Agarre Abierto', 'barbell-decline-wide-grip-press.gif', 'chest', '["Lie on a decline bench with your feet secured and your head lower than your hips.", "Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.", "Lower the barbell to your chest, keeping your elbows out to the sides.", "Push the barbell back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', '["Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas.", "Agarra la barra con un agarre amplio, un poco más ancho que la separación de los hombros.", "Baja la barra hacia el pecho, manteniendo los codos hacia los lados.", "Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Press Declinado con Barra y Agarre Supino', 'barbell-reverse-grip-decline-bench-press.gif', 'chest', '["Lie on a decline bench with your feet secured and your head lower than your hips.", "Grasp the barbell with a reverse grip, slightly wider than shoulder-width apart.", "Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.", "Pause for a moment at the bottom, then push the barbell back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas.", "Agarra la barra con un agarre invertido, un poco más ancho que la separación de los hombros.", "Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo.", "Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Press Declinado con Mancuernas', 'dumbbell-decline-bench-press.gif', 'chest', '["Lie down on a decline bench with your feet secured and your head lower than your hips.", "Hold a dumbbell in each hand and extend your arms straight up above your chest, palms facing forward.", "Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle.", "Push the dumbbells back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', '["Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas.", "Sostén una mancuerna en cada mano y extiende los brazos rectos hacia arriba por encima del pecho, con las palmas hacia adelante.", "Baja lentamente las mancuernas hacia los lados del pecho, manteniendo los codos en un ángulo de 90 grados.", "Empuja las mancuernas de nuevo hacia arriba hasta la posición inicial, extendiendo completamente los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Press Declinado con Mancuernas y Agarre Neutro', 'dumbbell-decline-hammer-press.gif', 'chest', '["Lie on a decline bench with your feet secured and your head lower than your hips.", "Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.", "Lower the dumbbells to the sides of your chest, keeping your elbows slightly bent.", "Press the dumbbells back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', '["Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas.", "Sostén una mancuerna en cada mano con las palmas enfrentadas entre sí y los brazos extendidos por encima del pecho.", "Baja las mancuernas a los lados del pecho, manteniendo los codos ligeramente flexionados.", "Empuja las mancuernas de nuevo hacia arriba hasta la posición inicial, extendiendo completamente los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Press Declinado en Máquina', 'lever-decline-chest-press.gif', 'chest', '["Adjust the seat height and backrest of the leverage machine to a comfortable position.", "Sit on the machine with your back against the backrest and your feet flat on the floor.", "Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.", "Push the handles forward and away from your body until your arms are fully extended.", "Slowly lower the handles back towards your chest, keeping your elbows slightly bent.", "Pause for a moment at the bottom, then push the handles back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura del asiento y el respaldo de la máquina de palanca a una posición cómoda.", "Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos en el suelo.", "Sujeta las asas con un agarre prono y coloca las manos un poco más separadas que la altura de los hombros.", "Empuja las asas hacia adelante y alejándolas del cuerpo hasta que los brazos queden completamente extendidos.", "Baja lentamente las asas de vuelta hacia el pecho, manteniendo los codos ligeramente flexionados.", "Haz una pausa breve en la parte baja, luego empuja las asas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Press Declinado en Máquina Smith', 'smith-decline-bench-press.gif', 'chest', '["Adjust the decline bench to the desired angle.", "Lie down on the bench with your feet secured under the foot pads.", "Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.", "Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.", "Pause for a moment at the bottom, then push the barbell back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta el banco declinado al ángulo deseado.", "Túmbate en el banco con los pies asegurados bajo las almohadillas para los pies.", "Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.", "Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo.", "Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Press Declinado en Máquina Smith con Agarre Abierto', 'smith-wide-grip-decline-bench-press.gif', 'chest', '["Adjust the decline bench to the desired angle.", "Lie down on the bench with your feet secured under the foot pads.", "Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.", "Unrack the barbell and lower it slowly towards your chest, keeping your elbows pointed outwards.", "Pause for a moment when the barbell touches your chest.", "Push the barbell back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', '["Ajusta el banco declinado al ángulo deseado.", "Túmbate en el banco con los pies asegurados bajo las almohadillas para los pies.", "Agarra la barra con un agarre amplio, un poco más ancho que la separación de los hombros.", "Desengancha la barra y bájala lentamente hacia tu pecho, manteniendo los codos apuntando hacia afuera.", "Haz una pausa breve cuando la barra toque el pecho.", "Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Press Declinado en Máquina Smith con Agarre Supino', 'smith-decline-reverse-grip-press.gif', 'chest', '["Adjust the smith machine to a decline position.", "Lie down on the bench with your feet secured under the foot pads.", "Grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.", "Unrack the barbell and lower it towards your chest, keeping your elbows tucked in.", "Pause for a moment at the bottom, then push the barbell back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la máquina Smith a una posición declinada.", "Túmbate en el banco con los pies asegurados bajo las almohadillas para los pies.", "Agarra la barra con un agarre invertido, manos un poco más separadas que el ancho de los hombros.", "Suelta la barra y bájala hacia el pecho, manteniendo los codos pegados al cuerpo.", "Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Press Declinado en Polea', 'cable-decline-press.gif', 'chest', '["Adjust the cable machine to a decline position.", "Sit on the decline bench facing the cable machine.", "Grasp the handles with an overhand grip and position them at chest level.", "Keep your feet flat on the ground and your back firmly against the bench.", "Exhale and push the handles away from your body, extending your arms fully.", "Pause for a moment at the end of the movement, squeezing your chest muscles.", "Inhale and slowly return the handles back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la máquina de cable a una posición declinada.", "Siéntate en el banco declinado frente a la máquina de cable.", "Sujeta las agarraderas con agarre prono y colócalas a la altura del pecho.", "Mantén los pies planos en el suelo y la espalda firmemente apoyada en el banco.", "Exhala y empuja las agarraderas alejándolas del cuerpo, extendiendo completamente los brazos.", "Haz una pausa breve al final del movimiento, contrayendo los músculos del pecho.", "Inhala y vuelve lentamente las agarraderas a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Press en el Suelo a 1 Brazo con Kettlebell', 'kettlebell-one-arm-floor-press.gif', 'chest', '["Lie flat on your back on the floor with your knees bent and feet flat on the ground.", "Hold the kettlebell in one hand with your palm facing towards your feet and your arm extended straight up towards the ceiling.", "Slowly lower the kettlebell towards your chest by bending your elbow, keeping your upper arm close to your body.", "Pause for a moment when the kettlebell is just above your chest, then push it back up to the starting position by extending your elbow.", "Repeat for the desired number of repetitions, then switch to the other arm."]', '["Túmbate boca arriba en el suelo con las rodillas flexionadas y los pies planos sobre el suelo.", "Sujeta la pesa rusa con una mano con la palma hacia los pies y el brazo extendido recto hacia el techo.", "Baja lentamente la pesa rusa hacia el pecho flexionando el codo, manteniendo el brazo superior cerca del cuerpo.", "Haz una pausa cuando la pesa rusa esté justo encima del pecho, luego empújala de vuelta hacia arriba a la posición inicial extendiendo el codo.", "Repite el número de repeticiones deseado, luego cambia al otro brazo."]'),
  ('Press Guillotina con Barra', 'barbell-guillotine-bench-press.gif', 'chest', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.", "Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.", "Lower the barbell slowly towards your neck, keeping your elbows pointed outwards.", "Pause for a moment when the barbell is just above your neck.", "Push the barbell back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.", "Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.", "Baja la barra lentamente hacia el cuello, manteniendo los codos apuntando hacia afuera.", "Haz una pausa breve cuando la barra esté justo encima del cuello.", "Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Press Inclinado a 1 Brazo con Mancuerna', 'dumbbell-incline-one-arm-press.gif', 'chest', '["Sit on an incline bench with a dumbbell in one hand, resting on your thigh.", "Lie back on the bench and position the dumbbell at shoulder level, palm facing forward.", "Press the dumbbell upward and slightly inward, extending your arm fully.", "Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."]', '["Siéntate en un banco inclinado con una mancuerna en una mano, apoyada sobre el muslo.", "Recuéstate en el banco y coloca la mancuerna a la altura del hombro, con la palma hacia adelante.", "Empuja la mancuerna hacia arriba y ligeramente hacia adentro, extendiendo completamente el brazo.", "Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia al otro brazo."]'),
  ('Press Inclinado a 1 Brazo con Mancuerna sobre Fitball', 'dumbbell-incline-one-arm-press-on-exercise-ball.gif', 'chest', '["Sit on an exercise ball with a dumbbell in one hand, feet flat on the ground.", "Slowly walk your feet forward, rolling the ball until your head, neck, and upper back are supported on the ball.", "Hold the dumbbell at shoulder height with your palm facing forward.", "Press the dumbbell upward until your arm is fully extended.", "Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."]', '["Siéntate sobre un balón de estabilidad con una mancuerna en una mano, con los pies apoyados en el suelo.", "Camina lentamente con los pies hacia adelante, haciendo rodar el balón hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón.", "Sostén la mancuerna a la altura del hombro con la palma hacia adelante.", "Empuja la mancuerna hacia arriba hasta que el brazo quede completamente extendido.", "Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia al otro brazo."]'),
  ('Press Inclinado a 1 Brazo en Polea', 'cable-one-arm-incline-press.gif', 'chest', '["Adjust the cable machine to a low pulley position.", "Sit on an incline bench facing away from the cable machine.", "Grasp the handle with one hand and bring it up to shoulder height.", "Position your feet firmly on the ground and maintain a stable position.", "Press the handle forward and upward, extending your arm fully.", "Pause for a moment at the top, then slowly lower the handle back to the starting position.", "Repeat for the desired number of repetitions, then switch sides."]', '["Ajusta la máquina de cable a una posición de polea baja.", "Siéntate en un banco inclinado de espaldas a la máquina de cable.", "Sujeta la agarradera con una mano y llévala hasta la altura del hombro.", "Coloca los pies firmemente en el suelo y mantén una posición estable.", "Empuja la agarradera hacia adelante y hacia arriba, extendiendo el brazo por completo.", "Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Press Inclinado a 1 Brazo en Polea sobre Fitball', 'cable-one-arm-incline-press-on-exercise-ball.gif', 'chest', '["Sit on an exercise ball with your feet flat on the ground and your back resting against an incline bench.", "Hold a cable handle in one hand and position your arm at a 90-degree angle with your elbow bent.", "Press the cable handle forward and upward, extending your arm fully.", "Pause for a moment at the top, then slowly lower the cable handle back to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."]', '["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda contra un banco inclinado.", "Sujeta una agarradera del cable con una mano y coloca el brazo en un ángulo de 90 grados con el codo flexionado.", "Empuja la agarradera del cable hacia adelante y hacia arriba, extendiendo el brazo por completo.", "Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia al otro brazo."]'),
  ('Press Inclinado Alterno con Mancuernas', 'dumbbell-incline-alternate-press.gif', 'chest', '["Sit on an incline bench with a dumbbell in each hand, resting on your thighs.", "Lean back on the bench and use your thighs to help raise the dumbbells to shoulder height, palms facing forward.", "Once at shoulder height, rotate your wrists so that the palms of your hands are facing forward.", "Push the dumbbells up with your chest and shoulders, extending your arms fully.", "Lower the dumbbells back down to the starting position, keeping your elbows slightly bent.", "Repeat for the desired number of repetitions, alternating arms."]', '["Siéntate en un banco inclinado con una mancuerna en cada mano, apoyadas sobre los muslos.", "Recuéstate en el banco y usa los muslos para ayudar a levantar las mancuernas hasta la altura de los hombros, con las palmas hacia adelante.", "Una vez a la altura de los hombros, gira las muñecas de modo que las palmas de las manos queden mirando hacia adelante.", "Empuja las mancuernas hacia arriba con el pecho y los hombros, extendiendo completamente los brazos.", "Baja las mancuernas de nuevo hasta la posición inicial, manteniendo los codos ligeramente flexionados.", "Repite el número de repeticiones deseado, alternando los brazos."]'),
  ('Press Inclinado con Barra y Agarre Supino', 'barbell-reverse-grip-incline-bench-press.gif', 'chest', '["Set up an incline bench at a 45-degree angle.", "Lie down on the bench with your feet flat on the ground.", "Grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.", "Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.", "Pause for a moment when the barbell touches your chest.", "Push the barbell back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', '["Coloca un banco inclinado a un ángulo de 45 grados.", "Túmbate en el banco con los pies planos sobre el suelo.", "Agarra la barra con un agarre invertido, manos un poco más separadas que el ancho de los hombros.", "Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo.", "Haz una pausa breve cuando la barra toque el pecho.", "Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Press Inclinado con Mancuernas', 'dumbbell-incline-bench-press.gif', 'chest', '["Set up an incline bench at a 45-degree angle.", "Sit on the bench with your feet flat on the ground and your back pressed firmly against the bench.", "Hold a dumbbell in each hand, palms facing forward, and lift them to shoulder height.", "Slowly lower the dumbbells to the sides of your chest, keeping your elbows at a 90-degree angle.", "Push the dumbbells back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', '["Coloca un banco inclinado a un ángulo de 45 grados.", "Siéntate en el banco con los pies apoyados en el suelo y la espalda firmemente apoyada contra el banco.", "Sostén una mancuerna en cada mano, con las palmas hacia adelante, y levántalas hasta la altura de los hombros.", "Baja lentamente las mancuernas hacia los lados del pecho, manteniendo los codos en un ángulo de 90 grados.", "Empuja las mancuernas de nuevo hacia arriba hasta la posición inicial, extendiendo completamente los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Press Inclinado con Mancuernas sobre Fitball', 'dumbbell-incline-press-on-exercise-ball.gif', 'chest', '["Sit on an exercise ball with a dumbbell in each hand, palms facing forward.", "Slowly walk your feet forward, rolling your body down the ball until your head, neck, and upper back are supported on the ball.", "Hold the dumbbells at shoulder level, elbows bent and pointing out to the sides.", "Press the dumbbells upward, extending your arms fully.", "Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate sobre un balón de estabilidad con una mancuerna en cada mano, con las palmas hacia adelante.", "Camina lentamente con los pies hacia adelante, bajando el cuerpo rodando sobre el balón hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón.", "Sostén las mancuernas a la altura de los hombros, con los codos flexionados y apuntando hacia los lados.", "Empuja las mancuernas hacia arriba, extendiendo completamente los brazos.", "Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Press Inclinado con Mancuernas y Agarre Neutro', 'dumbbell-incline-hammer-press.gif', 'chest', '["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, resting on your thighs.", "Lie back on the bench and position the dumbbells at shoulder level with your palms facing each other.", "Press the dumbbells up and away from your body until your arms are fully extended.", "Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, apoyadas sobre los muslos.", "Recuéstate en el banco y coloca las mancuernas a la altura de los hombros con las palmas enfrentadas entre sí.", "Empuja las mancuernas hacia arriba y alejándolas del cuerpo hasta que los brazos queden completamente extendidos.", "Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Press Inclinado en Máquina', 'lever-incline-chest-press.gif', 'chest', '["Adjust the seat and backrest of the leverage machine to a comfortable position.", "Sit on the machine with your back against the backrest and your feet flat on the floor.", "Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.", "Push the handles forward and away from your body until your arms are fully extended.", "Pause for a moment, then slowly bend your elbows and lower the handles back towards your chest.", "Repeat for the desired number of repetitions."]', '["Ajusta el asiento y el respaldo de la máquina de palanca a una posición cómoda.", "Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos en el suelo.", "Sujeta las asas con un agarre prono y coloca las manos un poco más separadas que la altura de los hombros.", "Empuja las asas hacia adelante y alejándolas del cuerpo hasta que los brazos queden completamente extendidos.", "Haz una pausa breve, luego flexiona lentamente los codos y baja las asas de vuelta hacia el pecho.", "Repite el número de repeticiones deseado."]'),
  ('Press Inclinado en Máquina Smith', 'smith-incline-bench-press.gif', 'chest', '["Adjust the bench to a 30-45 degree incline.", "Sit on the bench with your back flat against the pad and feet firmly on the ground.", "Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.", "Unrack the barbell and lower it slowly towards your upper chest, keeping your elbows slightly tucked in.", "Pause for a moment at the bottom, then push the barbell back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', '["Ajusta el banco a una inclinación de 30-45 grados.", "Siéntate en el banco con la espalda plana contra la almohadilla y los pies firmemente apoyados en el suelo.", "Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.", "Suelta la barra y bájala lentamente hacia la parte alta del pecho, manteniendo los codos ligeramente pegados al cuerpo.", "Haz una pausa por un momento en la posición baja, luego empuja la barra de vuelta a la posición inicial, extendiendo los brazos por completo.", "Repite el número de repeticiones deseado."]'),
  ('Press Inclinado en Máquina Smith con Agarre Supino', 'smith-incline-reverse-grip-press.gif', 'chest', '["Adjust the seat of the smith machine to a comfortable incline angle.", "Sit on the machine with your back against the pad and your feet flat on the ground.", "Grasp the bar with an overhand grip that is slightly wider than shoulder-width apart.", "Unrack the bar and lower it slowly towards your chest, keeping your elbows tucked in.", "Pause for a moment when the bar is just above your chest.", "Push the bar back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', '["Ajusta el asiento de la máquina Smith a un ángulo de inclinación cómodo.", "Siéntate en la máquina con la espalda contra la almohadilla y los pies planos sobre el suelo.", "Sujeta la barra con un agarre prono un poco más ancho que el ancho de los hombros.", "Suelta la barra y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo.", "Haz una pausa por un momento cuando la barra esté justo por encima del pecho.", "Empuja la barra de vuelta a la posición inicial, extendiendo los brazos por completo.", "Repite el número de repeticiones deseado."]'),
  ('Press Inclinado en Polea', 'cable-incline-bench-press.gif', 'chest', '["Adjust the bench to a 45-degree incline.", "Attach the cable handles to the high pulleys.", "Sit on the bench facing the cable machine with your feet flat on the ground.", "Grasp the handles with an overhand grip and bring them to shoulder height.", "Push the handles forward and upward until your arms are fully extended.", "Pause for a moment, then slowly lower the handles back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta el banco a una inclinación de 45 grados.", "Sujeta las agarraderas del cable a las poleas altas.", "Siéntate en el banco frente a la máquina de cable con los pies apoyados planos en el suelo.", "Sujeta las agarraderas con un agarre prono y llévalas a la altura de los hombros.", "Empuja las agarraderas hacia adelante y hacia arriba hasta que los brazos queden completamente extendidos.", "Haz una pausa por un momento y luego baja lentamente las agarraderas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Press Svend con Disco', 'weighted-svend-press.gif', 'chest', '["Stand with your feet shoulder-width apart and hold a weight plate in front of your chest with both hands.", "Keep your elbows slightly bent and your palms facing each other.", "Press the weight plate straight out in front of you, fully extending your arms.", "Pause for a moment at the end of the movement, then slowly bring the weight plate back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sostén un disco de peso frente al pecho con ambas manos.", "Mantén los codos ligeramente flexionados y las palmas mirándose entre sí.", "Empuja el disco de peso recto hacia adelante, extendiendo completamente los brazos.", "Haz una pausa de un momento al final del movimiento, luego lleva lentamente el disco de peso de nuevo a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Pullover a 1 Brazo con Mancuerna sobre Fitball', 'dumbbell-one-arm-pullover-on-exercise-ball.gif', 'chest', '["Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.", "Hold a dumbbell with one hand and extend your arm straight up above your chest.", "Slowly lower the dumbbell behind your head while keeping your arm straight.", "Pause for a moment, then raise the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y las rodillas flexionadas en un ángulo de 90 grados.", "Sostén una mancuerna con una mano y extiende el brazo recto hacia arriba sobre el pecho.", "Baja lentamente la mancuerna detrás de la cabeza manteniendo el brazo recto.", "Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Pullover Circular con Mancuerna', 'dumbbell-around-pullover.gif', 'chest', '["Lie flat on a bench with your head at one end and your feet firmly on the ground.", "Hold a dumbbell with both hands and extend your arms straight above your chest.", "Keeping your arms straight, slowly lower the dumbbell behind your head in an arc motion.", "Pause for a moment at the bottom, then raise the dumbbell back to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate en un banco con la cabeza en un extremo y los pies firmemente apoyados en el suelo.", "Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima del pecho.", "Manteniendo los brazos rectos, baja lentamente la mancuerna detrás de la cabeza en un movimiento de arco.", "Haz una pausa breve en la parte baja, luego levanta la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Pullover con Barra en Banco Declinado', 'barbell-decline-pullover.gif', 'chest', '["Lie down on a decline bench with your head lower than your hips and your feet secured.", "Hold the barbell with a pronated grip (palms facing away from you) and your hands slightly wider than shoulder-width apart.", "Extend your arms above your chest, keeping a slight bend in your elbows.", "Lower the barbell in an arc motion behind your head, feeling a stretch in your chest and shoulders.", "Pause for a moment, then return the barbell to the starting position by reversing the motion.", "Repeat for the desired number of repetitions."]', '["Túmbate en un banco declinado con la cabeza más baja que las caderas y los pies sujetos.", "Sujeta la barra con un agarre pronado (palmas mirando hacia afuera) y las manos un poco más separadas que el ancho de los hombros.", "Extiende los brazos por encima del pecho, manteniendo una ligera flexión en los codos.", "Baja la barra describiendo un arco detrás de la cabeza, sintiendo un estiramiento en el pecho y los hombros.", "Haz una pausa breve y luego devuelve la barra a la posición inicial invirtiendo el movimiento.", "Repite el número de repeticiones deseado."]'),
  ('Pullover con Extensión de Cadera sobre Fitball', 'dumbbell-pullover-hip-extension-on-exercise-ball.gif', 'chest', '["Sit on an exercise ball with your feet flat on the ground and the dumbbell resting on your thighs.", "Slowly walk your feet forward, rolling the exercise ball down your back until your head, neck, and upper back are supported on the ball.", "Hold the dumbbell with both hands and extend your arms straight up over your chest, keeping a slight bend in your elbows.", "Lower the dumbbell behind your head, keeping your arms straight and maintaining control.", "Pause for a moment, then raise the dumbbell back to the starting position.", "While keeping your arms extended, lift your hips off the ground, squeezing your glutes and engaging your core.", "Lower your hips back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate sobre un balón de estabilidad con los pies planos en el suelo y la mancuerna apoyada sobre los muslos.", "Camina lentamente hacia adelante con los pies, haciendo rodar el balón de estabilidad por tu espalda hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón.", "Sujeta la mancuerna con ambas manos y extiende los brazos rectos por encima del pecho, manteniendo una ligera flexión en los codos.", "Baja la mancuerna detrás de la cabeza, manteniendo los brazos rectos y con control total.", "Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial.", "Manteniendo los brazos extendidos, levanta las caderas del suelo, apretando los glúteos y activando el core.", "Baja las caderas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Pullover con Mancuerna', 'dumbbell-pullover.gif', 'chest', '["Lie flat on a bench with your head at one end and your feet on the floor.", "Hold a dumbbell with both hands and extend your arms straight above your chest.", "Keeping a slight bend in your elbows, slowly lower the dumbbell behind your head until you feel a stretch in your chest and shoulders.", "Pause for a moment, then raise the dumbbell back to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo.", "Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima del pecho.", "Manteniendo una ligera flexión en los codos, baja lentamente la mancuerna detrás de la cabeza hasta sentir un estiramiento en el pecho y los hombros.", "Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Pullover con Mancuerna Tumbado sobre Fitball', 'dumbbell-lying-pullover-on-exercise-ball.gif', 'chest', '["Sit on an exercise ball and roll forward until your upper back is resting on the ball.", "Hold a dumbbell with both hands and extend your arms straight up over your chest.", "Slowly lower the dumbbell behind your head while keeping your arms straight.", "Pause for a moment, then raise the dumbbell back to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate sobre un balón de estabilidad y rueda hacia adelante hasta que la parte superior de la espalda quede apoyada en el balón.", "Sostén una mancuerna con ambas manos y extiende los brazos rectos hacia arriba sobre el pecho.", "Baja lentamente la mancuerna detrás de la cabeza manteniendo los brazos rectos.", "Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Pullover con Mancuerna y Brazos Rectos', 'dumbbell-straight-arm-pullover.gif', 'chest', '["Lie flat on a bench with your head at one end and your feet planted firmly on the ground.", "Hold a dumbbell with both hands and extend your arms straight above your chest.", "Keeping your arms straight, slowly lower the dumbbell behind your head in an arc-like motion.", "Pause for a moment, then raise the dumbbell back to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate en un banco con la cabeza en un extremo y los pies firmemente apoyados en el suelo.", "Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima del pecho.", "Manteniendo los brazos rectos, baja lentamente la mancuerna detrás de la cabeza con un movimiento en forma de arco.", "Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Pullover Respiratorio con Mancuernas en Banco Inclinado', 'dumbbell-incline-breeding.gif', 'chest', '["Set up an incline bench at a 45-degree angle.", "Sit on the bench with your back against the pad and feet flat on the ground.", "Hold a dumbbell in each hand with an overhand grip, palms facing forward.", "Start with your arms fully extended, perpendicular to the ground.", "Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle.", "Pause for a moment at the bottom, then push the dumbbells back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Coloca un banco inclinado a un ángulo de 45 grados.", "Siéntate en el banco con la espalda apoyada en el respaldo y los pies planos sobre el suelo.", "Sostén una mancuerna en cada mano con agarre prono, con las palmas hacia adelante.", "Comienza con los brazos completamente extendidos, perpendiculares al suelo.", "Baja lentamente las mancuernas hacia los lados del pecho, manteniendo los codos en un ángulo de 90 grados.", "Haz una pausa por un momento en la parte inferior, luego empuja las mancuernas de nuevo hacia arriba hasta la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Agarre en Máquina (Gripper)', 'lever-gripper-hands.gif', 'lower arms', '["Adjust the seat height and grip the handles of the leverage machine.", "Keep your back straight and your feet flat on the ground.", "Exhale and squeeze the handles, contracting your forearms.", "Hold the contraction for a second, then slowly release and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura del asiento y sujeta las asas de la máquina de palanca.", "Mantén la espalda recta y los pies planos en el suelo.", "Exhala y aprieta las asas, contrayendo los antebrazos.", "Mantén la contracción durante un segundo, luego suelta lentamente y vuelve a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Apretón de Disco de Pie', 'weighted-standing-hand-squeeze.gif', 'lower arms', '["Stand with your feet shoulder-width apart and hold a weight in each hand.", "Extend your arms straight in front of you, palms facing each other.", "Squeeze your hands together as hard as you can, engaging your forearms.", "Hold the squeeze for a few seconds, then release.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sostén un peso en cada mano.", "Extiende los brazos rectos hacia adelante, con las palmas mirándose entre sí.", "Aprieta las manos entre sí con la mayor fuerza posible, activando los antebrazos.", "Mantén la contracción durante unos segundos y luego suelta.", "Repite el número de repeticiones deseado."]'),
  ('Cargada Colgante Alterna con Kettlebell', 'kettlebell-alternating-hang-clean.gif', 'lower arms', '["Stand with your feet shoulder-width apart, holding a kettlebell in each hand with an overhand grip.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.", "Allow the kettlebells to hang in front of your body with your arms fully extended.", "In one fluid motion, explosively extend your hips, shrug your shoulders, and pull the kettlebells up towards your shoulders.", "As the kettlebells reach shoulder height, rotate your wrists and catch the kettlebells in the rack position, with your palms facing inward and the kettlebells resting on the outside of your forearms.", "Lower the kettlebells back down to the starting position and repeat the movement with the opposite arm.", "Continue alternating arms for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano con agarre prono.", "Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado.", "Deja que las pesas rusas cuelguen frente al cuerpo con los brazos completamente extendidos.", "En un solo movimiento fluido, extiende las caderas de forma explosiva, encoge los hombros y tira de las pesas rusas hacia los hombros.", "Cuando las pesas rusas alcancen la altura de los hombros, gira las muñecas y atrápalas en posición de descanso, con las palmas hacia adentro y las pesas rusas apoyadas en la parte externa de los antebrazos.", "Baja las pesas rusas de nuevo a la posición inicial y repite el movimiento con el brazo opuesto.", "Continúa alternando los brazos durante el número de repeticiones deseado."]'),
  ('Curl de Dedos con Barra', 'finger-curls.gif', 'lower arms', '["Sit on a bench with your feet flat on the ground and hold a barbell with an underhand grip, palms facing up.", "Rest your forearms on your thighs, allowing your wrists to hang off the edge.", "Slowly curl your fingers towards your palms, squeezing the barbell tightly.", "Hold the contraction for a moment, then slowly release your fingers back to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco con los pies planos sobre el suelo y sujeta una barra con un agarre supino, con las palmas hacia arriba.", "Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde.", "Curva lentamente los dedos hacia las palmas, apretando la barra con fuerza.", "Mantén la contracción por un momento, luego suelta lentamente los dedos hasta la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Dedos con Mancuernas', 'dumbbell-finger-curls-1437.gif', 'lower arms', '["Sit on a bench or chair with your feet flat on the ground and your back straight.", "Hold a dumbbell in one hand with an underhand grip, resting your forearm on your thigh, palm facing up.", "Allow the dumbbell to roll down to your fingertips, then curl it back up by flexing your fingers.", "Repeat for the desired number of repetitions, then switch to the other hand."]', '["Siéntate en un banco o silla con los pies apoyados en el suelo y la espalda recta.", "Sostén una mancuerna en una mano con agarre supino, apoyando el antebrazo sobre el muslo, con la palma hacia arriba.", "Deja que la mancuerna ruede hacia las puntas de los dedos, luego flexiona los dedos para volver a enrollarla hacia arriba.", "Repite el número de repeticiones deseado, luego cambia a la otra mano."]'),
  ('Curl de Muñeca a 1 Brazo con Mancuerna', 'dumbbell-one-arm-wrist-curl.gif', 'lower arms', '["Sit on a bench or chair with your feet flat on the ground.", "Hold a dumbbell in one hand with an underhand grip, resting your forearm on your thigh.", "Allow your wrist to extend, letting the dumbbell roll down towards your fingers.", "Slowly curl your wrist back up, bringing the dumbbell towards your forearm.", "Repeat for the desired number of repetitions, then switch to the other hand."]', '["Siéntate en un banco o silla con los pies apoyados en el suelo.", "Sostén una mancuerna en una mano con agarre supino, apoyando el antebrazo sobre el muslo.", "Permite que la muñeca se extienda, dejando que la mancuerna ruede hacia los dedos.", "Flexiona lentamente la muñeca hacia arriba, acercando la mancuerna hacia el antebrazo.", "Repite el número de repeticiones deseado, luego cambia a la otra mano."]'),
  ('Curl de Muñeca a 1 Brazo con Mancuerna sobre Banco', 'dumbbell-over-bench-one-arm-wrist-curl.gif', 'lower arms', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing down.", "Rest your forearm on the bench with your wrist hanging off the edge.", "Slowly curl your wrist upwards, bringing the dumbbell towards your forearm.", "Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."]', '["Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna con una mano, con la palma hacia abajo.", "Apoya el antebrazo en el banco con la muñeca colgando del borde.", "Flexiona lentamente la muñeca hacia arriba, acercando la mancuerna hacia el antebrazo.", "Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia al otro brazo."]'),
  ('Curl de Muñeca con Barra sobre Banco', 'barbell-palms-up-wrist-curl-over-a-bench.gif', 'lower arms', '["Sit on a bench with your feet flat on the ground and hold a barbell with an underhand grip, palms facing up.", "Rest your forearms on the bench, allowing your wrists to hang off the edge.", "Keeping your forearms stationary, exhale and curl your wrists upwards as far as possible.", "Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco con los pies planos sobre el suelo y sujeta una barra con un agarre supino, con las palmas hacia arriba.", "Apoya los antebrazos sobre el banco, dejando que las muñecas cuelguen del borde.", "Manteniendo los antebrazos fijos, exhala y flexiona las muñecas hacia arriba tanto como sea posible.", "Mantén la posición contraída durante una breve pausa, luego inhala y baja lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Muñeca con Mancuernas sobre Banco', 'dumbbell-over-bench-wrist-curl.gif', 'lower arms', '["Sit on a bench with your forearms resting on the bench and your palms facing up, holding a dumbbell in each hand.", "Allow your wrists to hang over the edge of the bench.", "Slowly curl your wrists upward, squeezing your forearms at the top of the movement.", "Pause for a moment, then slowly lower your wrists back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco con los antebrazos apoyados en él y las palmas hacia arriba, sujetando una mancuerna en cada mano.", "Deja que tus muñecas cuelguen del borde del banco.", "Flexiona lentamente las muñecas hacia arriba, apretando los antebrazos en la parte superior del movimiento.", "Haz una pausa por un momento y luego baja lentamente las muñecas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Muñeca de Pie con Barra por Detrás', 'barbell-standing-back-wrist-curl.gif', 'lower arms', '["Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip.", "Rest the barbell on the back of your hands with your palms facing down and your fingers pointing towards your body.", "Keeping your upper arms stationary, exhale and curl your wrists upwards as far as possible.", "Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono.", "Apoya la barra sobre el dorso de las manos con las palmas hacia abajo y los dedos apuntando hacia el cuerpo.", "Manteniendo los brazos superiores quietos, exhala y flexiona las muñecas hacia arriba lo más posible.", "Mantén la posición contraída durante una breve pausa, luego inhala y baja lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Muñeca de Pie en Polea por Detrás', 'cable-standing-back-wrist-curl.gif', 'lower arms', '["Stand facing a cable machine with your feet shoulder-width apart.", "Hold the cable handle with an overhand grip, palms facing down.", "Keep your arms straight and your elbows close to your sides.", "Slowly curl your wrists upward, bringing the cable handle towards your body.", "Pause for a moment at the top, then slowly lower the cable handle back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.", "Sujeta el mango del cable con un agarre prono, con las palmas hacia abajo.", "Mantén los brazos rectos y los codos cerca de los costados.", "Flexiona lentamente las muñecas hacia arriba, llevando el mango del cable hacia tu cuerpo.", "Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Muñeca de Pie por Detrás en Máquina Smith', 'smith-standing-back-wrist-curl.gif', 'lower arms', '["Stand facing the smith machine with your feet shoulder-width apart.", "Grasp the barbell with an overhand grip, hands shoulder-width apart.", "Keep your back straight and your elbows close to your body.", "Slowly curl your wrists upwards, bringing the barbell towards your body.", "Pause for a moment at the top, then slowly lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie frente a la máquina Smith con los pies separados a la altura de los hombros.", "Sujeta la barra con un agarre prono, con las manos separadas a la altura de los hombros.", "Mantén la espalda recta y los codos cerca del cuerpo.", "Flexiona lentamente las muñecas hacia arriba, llevando la barra hacia el cuerpo.", "Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Muñeca en Polea', 'cable-wrist-curl.gif', 'lower arms', '["Attach a straight bar to a low pulley cable machine.", "Stand facing the machine with your feet shoulder-width apart.", "Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.", "Rest your forearms on a bench or pad, with your wrists hanging off the edge.", "Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.", "Pause for a moment at the top, then inhale and slowly lower the bar back to the starting position.", "Repeat for the desired number of repetitions."]', '["Coloca una barra recta en una máquina de cable con polea baja.", "Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.", "Sujeta la barra con un agarre supino, con las palmas hacia arriba y las manos separadas a la altura de los hombros.", "Apoya los antebrazos en un banco o almohadilla, con las muñecas colgando del borde.", "Manteniendo los antebrazos fijos, exhala y flexiona las muñecas hacia arriba tanto como sea posible.", "Haz una pausa breve en la parte alta, luego inhala y baja lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Muñeca Inverso a 1 Brazo con Mancuerna', 'dumbbell-one-arm-reverse-wrist-curl.gif', 'lower arms', '["Sit on a bench or chair with your feet flat on the ground.", "Hold a dumbbell in one hand with an overhand grip, palm facing down.", "Rest your forearm on your thigh, with your wrist hanging off the edge.", "Slowly lower the dumbbell towards the ground by flexing your wrist.", "Pause for a moment at the bottom, then slowly curl your wrist back up towards your body.", "Repeat for the desired number of repetitions, then switch to the other arm."]', '["Siéntate en un banco o silla con los pies apoyados en el suelo.", "Sostén una mancuerna en una mano con agarre prono, con la palma hacia abajo.", "Apoya el antebrazo sobre el muslo, con la muñeca colgando fuera del borde.", "Baja lentamente la mancuerna hacia el suelo flexionando la muñeca.", "Haz una pausa por un momento en la parte inferior, luego flexiona lentamente la muñeca de vuelta hacia el cuerpo.", "Repite el número de repeticiones deseado, luego cambia al otro brazo."]'),
  ('Curl de Muñeca Inverso a 1 Brazo con Mancuerna sobre Banco', 'dumbbell-over-bench-one-arm-reverse-wrist-curl.gif', 'lower arms', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing down.", "Rest your forearm on the bench with your wrist hanging off the edge.", "Slowly curl your wrist upwards, bringing the dumbbell towards your forearm.", "Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."]', '["Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna con una mano, con la palma hacia abajo.", "Apoya el antebrazo en el banco con la muñeca colgando del borde.", "Flexiona lentamente la muñeca hacia arriba, acercando la mancuerna hacia el antebrazo.", "Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia al otro brazo."]'),
  ('Curl de Muñeca Inverso con Banda Elástica', 'band-reverse-wrist-curl.gif', 'lower arms', '["Sit on a bench or chair with your feet flat on the ground.", "Hold the band with an overhand grip, palms facing down, and wrap it around your fingers.", "Rest your forearms on your thighs, with your wrists hanging off the edge.", "Slowly curl your wrists upward, squeezing your forearms.", "Pause for a moment at the top, then slowly lower your wrists back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco o silla con los pies apoyados en el suelo.", "Sostén la banda con un agarre prono, con las palmas hacia abajo, y envuélvela alrededor de los dedos.", "Apoya los antebrazos sobre los muslos, con las muñecas colgando del borde.", "Flexiona lentamente las muñecas hacia arriba, apretando los antebrazos.", "Haz una pausa por un momento en la parte superior, luego baja lentamente las muñecas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Muñeca Inverso con Barra sobre Banco', 'barbell-palms-down-wrist-curl-over-a-bench.gif', 'lower arms', '["Sit on a bench with your feet flat on the ground and your forearms resting on your thighs, palms facing down.", "Hold a barbell with an overhand grip, hands shoulder-width apart.", "Lower the barbell towards the ground by flexing your wrists, keeping your forearms stationary.", "Pause for a moment at the bottom, then slowly raise the barbell back up by extending your wrists.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco con los pies planos sobre el suelo y los antebrazos apoyados sobre los muslos, con las palmas hacia abajo.", "Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros.", "Baja la barra hacia el suelo flexionando las muñecas, manteniendo los antebrazos fijos.", "Haz una pausa breve en la parte baja y luego levanta lentamente la barra extendiendo las muñecas.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Muñeca Inverso con Mancuernas', 'dumbbell-reverse-wrist-curl.gif', 'lower arms', '["Sit on a bench or chair with your feet flat on the ground.", "Hold a dumbbell in each hand with an overhand grip, palms facing down.", "Rest your forearms on your thighs, allowing your wrists to hang off the edge.", "Slowly curl your wrists upward, bringing the dumbbells towards your body.", "Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco o silla con los pies apoyados en el suelo.", "Sujeta una mancuerna en cada mano con agarre prono, con las palmas hacia abajo.", "Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde.", "Flexiona lentamente las muñecas hacia arriba, acercando las mancuernas hacia tu cuerpo.", "Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Muñeca Inverso con Mancuernas sobre Banco', 'dumbbell-over-bench-revers-wrist-curl.gif', 'lower arms', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing down.", "Rest your forearms on the bench, allowing your wrists to hang off the edge.", "Slowly curl your wrists upward, bringing the dumbbells towards your body.", "Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna en cada mano, con las palmas hacia abajo.", "Apoya los antebrazos sobre el banco, dejando que las muñecas cuelguen del borde.", "Flexiona lentamente las muñecas hacia arriba, acercando las mancuernas hacia tu cuerpo.", "Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Muñeca Inverso en Polea', 'cable-reverse-wrist-curl.gif', 'lower arms', '["Attach a cable to a low pulley and sit on a bench facing the cable machine.", "Grasp the cable handle with an overhand grip, palms facing down.", "Rest your forearms on your thighs, with your wrists hanging off the edge.", "Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.", "Pause for a moment at the top, then inhale and slowly lower your wrists back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Sujeta un cable a una polea baja y siéntate en un banco frente a la máquina de cable.", "Sujeta la agarradera del cable con un agarre prono, con las palmas hacia abajo.", "Apoya los antebrazos sobre los muslos, con las muñecas colgando del borde.", "Manteniendo los antebrazos fijos, exhala y flexiona las muñecas hacia arriba tanto como sea posible.", "Haz una pausa por un momento en la parte alta, luego inhala y baja lentamente las muñecas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Muñeca Neutro a 1 Brazo Sentado con Mancuerna', 'dumbbell-one-arm-seated-neutral-wrist-curl.gif', 'lower arms', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing up.", "Rest your forearm on your thigh, allowing your wrist to hang off the edge.", "Keeping your forearm stationary, curl your wrist upward as far as possible.", "Pause for a moment at the top, then slowly lower your wrist back down to the starting position.", "Repeat for the desired number of repetitions, then switch to the other hand."]', '["Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en una mano, con la palma hacia arriba.", "Apoya el antebrazo sobre el muslo, dejando que la muñeca cuelgue fuera del borde.", "Manteniendo el antebrazo quieto, flexiona la muñeca hacia arriba lo más posible.", "Haz una pausa por un momento en la parte superior, luego baja lentamente la muñeca de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia a la otra mano."]'),
  ('Curl de Muñeca Sentado en Máquina Smith', 'smith-seated-wrist-curl.gif', 'lower arms', '["Sit on a bench in front of a Smith machine with your feet flat on the ground.", "Grasp the barbell with an underhand grip, hands shoulder-width apart.", "Rest your forearms on your thighs, allowing your wrists to hang off.", "Slowly curl your wrists upward, bringing the barbell towards your forearms.", "Pause for a moment at the top, then slowly lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco frente a una máquina Smith con los pies planos sobre el suelo.", "Sujeta la barra con un agarre supino, con las manos separadas a la altura de los hombros.", "Apoya los antebrazos sobre los muslos, permitiendo que las muñecas cuelguen.", "Flexiona lentamente las muñecas hacia arriba, llevando la barra hacia los antebrazos.", "Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Círculos de Muñeca', 'wrist-circles.gif', 'lower arms', '["Extend your arms straight out in front of you.", "Make a fist with both hands.", "Rotate your wrists in a circular motion, keeping your arms still.", "Continue the wrist circles for the desired number of repetitions."]', '["Extiende los brazos rectos frente a ti.", "Cierra ambas manos en un puño.", "Gira las muñecas en un movimiento circular, manteniendo los brazos quietos.", "Continúa los círculos de muñeca el número de repeticiones deseado."]'),
  ('Estiramiento Lateral de Muñeca', 'side-wrist-pull-stretch.gif', 'lower arms', '["Stand with your feet shoulder-width apart and your arms extended in front of you.", "Extend your right arm out to the side, parallel to the ground, with your palm facing down.", "With your left hand, grab your right hand and gently pull it towards your body, feeling a stretch in your right forearm.", "Hold the stretch for 15-30 seconds, then release.", "Repeat on the other side."]', '["Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos frente a ti.", "Extiende el brazo derecho hacia el lado, paralelo al suelo, con la palma hacia abajo.", "Con la mano izquierda, sujeta la mano derecha y tira de ella suavemente hacia tu cuerpo, sintiendo un estiramiento en el antebrazo derecho.", "Mantén el estiramiento durante 15-30 segundos, luego suelta.", "Repite del otro lado."]'),
  ('Flexión Modificada sobre Antebrazos', 'modified-push-up-to-lower-arms.gif', 'lower arms', '["Start in a push-up position with your hands directly under your shoulders and your body in a straight line.", "Lower your body down towards the ground by bending your elbows, keeping them close to your sides.", "Once your elbows are at a 90-degree angle, lower your forearms to the ground, keeping your elbows directly under your shoulders.", "Pause for a moment, then push through your palms to lift your forearms back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza en posición de flexión con las manos directamente debajo de los hombros y el cuerpo en línea recta.", "Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de tu costado.", "Cuando los codos formen un ángulo de 90 grados, baja los antebrazos hasta el suelo, manteniendo los codos justo debajo de los hombros.", "Haz una pausa por un momento y luego empuja con las palmas para llevar los antebrazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Pronación Tumbado con Mancuerna', 'dumbbell-lying-pronation.gif', 'lower arms', '["Lie flat on a bench with your chest facing down and your arms extended straight down, holding a dumbbell in each hand.", "Rotate your palms so they are facing up.", "Keeping your upper arms stationary, exhale and curl the dumbbells as you rotate your palms to face down.", "Inhale and slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca abajo en un banco con el pecho hacia abajo y los brazos extendidos rectos hacia abajo, sosteniendo una mancuerna en cada mano.", "Gira las palmas de modo que queden mirando hacia arriba.", "Manteniendo los brazos superiores quietos, exhala y flexiona las mancuernas mientras giras las palmas hacia abajo.", "Inhala y baja lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Pronación Tumbado en el Suelo con Mancuerna', 'dumbbell-lying-pronation-on-floor.gif', 'lower arms', '["Lie flat on the floor with your face down and your arms extended straight out in front of you, holding a dumbbell in each hand.", "Rotate your palms so they are facing down towards the floor.", "Keeping your arms straight, lift the dumbbells off the floor by contracting your forearms.", "Continue lifting until your forearms are fully contracted and the dumbbells are at shoulder level.", "Hold for a moment, then slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca abajo en el suelo con los brazos extendidos rectos frente a ti, sosteniendo una mancuerna en cada mano.", "Gira las palmas de modo que queden mirando hacia el suelo.", "Manteniendo los brazos rectos, levanta las mancuernas del suelo contrayendo los antebrazos.", "Continúa levantando hasta que los antebrazos estén completamente contraídos y las mancuernas queden a la altura de los hombros.", "Mantén la posición por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Rotación de Antebrazo Sentado con Mancuerna', 'dumbbell-seated-one-arm-rotate.gif', 'lower arms', '["Sit on a bench with your back straight and hold a dumbbell in one hand, resting it on your thigh.", "Raise the dumbbell up to shoulder height, keeping your elbow close to your body.", "Rotate your forearm outward, away from your body, while keeping your upper arm stationary.", "Pause for a moment at the top, then slowly rotate your forearm back to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."]', '["Siéntate en un banco con la espalda recta y sujeta una mancuerna con una mano, apoyándola sobre el muslo.", "Sube la mancuerna hasta la altura del hombro, manteniendo el codo cerca de tu cuerpo.", "Gira el antebrazo hacia afuera, alejándolo de tu cuerpo, mientras mantienes fija la parte superior del brazo.", "Haz una pausa por un momento en la parte superior, luego gira lentamente el antebrazo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia al otro brazo."]'),
  ('Supinación Tumbado con Mancuerna', 'dumbbell-lying-supination.gif', 'lower arms', '["Lie flat on a bench with your feet flat on the ground.", "Hold a dumbbell in each hand with your palms facing up and your arms fully extended.", "Keeping your upper arms stationary, curl the dumbbells towards your shoulders by contracting your forearms.", "Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca arriba en un banco con los pies planos sobre el suelo.", "Sostén una mancuerna en cada mano con las palmas hacia arriba y los brazos completamente extendidos.", "Manteniendo los brazos superiores quietos, flexiona las mancuernas hacia los hombros contrayendo los antebrazos.", "Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Supinación Tumbado en el Suelo con Mancuerna', 'dumbbell-lying-supination-on-floor.gif', 'lower arms', '["Lie flat on your back on the floor with your legs extended and your arms by your sides, holding a dumbbell in each hand.", "Rotate your palms to face up, keeping your elbows close to your sides.", "Slowly curl the dumbbells towards your shoulders, squeezing your forearms.", "Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca arriba en el suelo con las piernas extendidas y los brazos a los costados, sosteniendo una mancuerna en cada mano.", "Gira las palmas hacia arriba, manteniendo los codos cerca de los costados.", "Flexiona lentamente las mancuernas hacia los hombros, contrayendo los antebrazos.", "Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Círculos de Rodilla', 'circles-knee-stretch.gif', 'lower legs', '["Stand with your feet shoulder-width apart and your hands on your hips.", "Bend your knees slightly and lift your heels off the ground, balancing on the balls of your feet.", "Keeping your knees bent, rotate your knees in a circular motion, first clockwise and then counterclockwise.", "Perform the movement for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y las manos en las caderas.", "Flexiona ligeramente las rodillas y levanta los talones del suelo, equilibrándote sobre las puntas de los pies.", "Manteniendo las rodillas flexionadas, gira las rodillas en un movimiento circular, primero en el sentido de las agujas del reloj y luego en sentido contrario.", "Realiza el movimiento el número de repeticiones deseado."]'),
  ('Círculos de Tobillo', 'ankle-circles.gif', 'lower legs', '["Sit on the ground with your legs extended in front of you.", "Lift one leg off the ground and rotate your ankle in a circular motion.", "Perform the desired number of circles in one direction, then switch to the other direction.", "Repeat with the other leg."]', '["Siéntate en el suelo con las piernas extendidas frente a ti.", "Levanta una pierna del suelo y rota el tobillo con un movimiento circular.", "Realiza el número de círculos deseado en una dirección, luego cambia a la dirección contraria.", "Repite con la otra pierna."]'),
  ('Elevación de Gemelo a 1 Pierna de Pie en Polea', 'cable-standing-one-leg-calf-raise.gif', 'lower legs', '["Stand facing a cable machine with your feet shoulder-width apart.", "Hold onto the cable machine for support.", "Lift one leg off the ground and balance on the other leg.", "Slowly raise your heel off the ground, lifting your body up onto your toes.", "Pause for a moment at the top, then slowly lower your heel back down to the starting position.", "Repeat for the desired number of repetitions, then switch legs."]', '["Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.", "Sujétate de la máquina de cable para apoyarte.", "Levanta una pierna del suelo y equilíbrate sobre la otra pierna.", "Levanta lentamente el talón del suelo, elevando el cuerpo sobre las puntas de los pies.", "Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de pierna."]'),
  ('Elevación de Gemelo a 1 Pierna en el Suelo', 'one-leg-floor-calf-raise.gif', 'lower legs', '["Stand with your feet hip-width apart and place your hands on a wall or sturdy object for balance.", "Lift one foot off the ground and balance on the other foot.", "Slowly raise your heel off the ground, lifting your body up onto the ball of your foot.", "Pause for a moment at the top, then slowly lower your heel back down to the starting position.", "Repeat for the desired number of repetitions, then switch legs and repeat."]', '["Ponte de pie con los pies separados a la altura de las caderas y coloca las manos en una pared u objeto firme para mantener el equilibrio.", "Levanta un pie del suelo y mantén el equilibrio sobre el otro pie.", "Levanta lentamente el talón del suelo, elevando el cuerpo sobre las puntas de los pies.", "Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial.", "Repite el número de repeticiones deseado y luego cambia de pierna y repite."]'),
  ('Elevación de Gemelo a 1 Pierna en Máquina Hack', 'hack-one-leg-calf-raise.gif', 'lower legs', '["Adjust the sled machine to an appropriate weight.", "Stand on the sled machine with one foot, keeping the other foot off the ground.", "Hold onto the handles for stability.", "Raise your heel as high as possible, lifting your body up on the ball of your foot.", "Pause for a moment at the top, then slowly lower your heel back down to the starting position.", "Repeat for the desired number of repetitions.", "Switch legs and repeat the exercise."]', '["Ajusta la máquina de trineo a un peso adecuado.", "Ponte de pie sobre la máquina de trineo con un pie, manteniendo el otro pie levantado del suelo.", "Sujétate de las asas para mantener el equilibrio.", "Levanta el talón lo más alto posible, elevando el cuerpo sobre la punta del pie.", "Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial.", "Repite el número de repeticiones deseado.", "Cambia de pierna y repite el ejercicio."]'),
  ('Elevación de Gemelo a 1 Pierna en Máquina Smith', 'smith-one-leg-floor-calf-raise.gif', 'lower legs', '["Position yourself on the floor under the smith machine bar, facing away from the machine.", "Place the balls of your feet on a raised surface, such as a weight plate or block.", "Position the smith machine bar across your lower legs, just above your ankles.", "Hold onto the bar with your hands for stability.", "Raise your heels off the ground by extending your ankles, lifting your body up.", "Pause at the top of the movement, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Colócate en el suelo debajo de la barra de la máquina Smith, mirando en dirección contraria a la máquina.", "Coloca la punta de los pies sobre una superficie elevada, como un disco de peso o un bloque.", "Coloca la barra de la máquina Smith sobre la parte baja de las piernas, justo por encima de los tobillos.", "Sujeta la barra con las manos para mayor estabilidad.", "Levanta los talones del suelo extendiendo los tobillos, elevando el cuerpo hacia arriba.", "Haz una pausa en la parte alta del movimiento, luego baja lentamente los talones de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Gemelo a 1 Pierna en Prensa', 'sled-one-leg-calf-press-on-leg-press.gif', 'lower legs', '["Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the sled.", "Sit on the machine with your back against the backrest and your feet on the sled, shoulder-width apart.", "Place your toes and the balls of your feet on the sled, keeping your heels off.", "Push the sled forward by extending your ankles, keeping your knees slightly bent.", "Pause for a moment at the top, then slowly lower the sled back down by flexing your ankles.", "Repeat for the desired number of repetitions."]', '["Ajusta el asiento de la máquina de prensa de piernas de modo que las rodillas queden ligeramente flexionadas cuando los pies estén sobre el trineo.", "Siéntate en la máquina con la espalda contra el respaldo y los pies sobre el trineo, separados a la altura de los hombros.", "Coloca la punta y la almohadilla de los pies sobre el trineo, manteniendo los talones levantados.", "Empuja el trineo hacia delante extendiendo los tobillos, manteniendo las rodillas ligeramente flexionadas.", "Haz una pausa por un momento en la posición alta, luego baja lentamente el trineo flexionando los tobillos.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Gemelo a 1 Pierna sobre Mancuerna', 'single-leg-calf-raise-on-a-dumbbell.gif', 'lower legs', '["Stand with your feet hip-width apart and hold a dumbbell in one hand.", "Lift one foot off the ground and balance on the other foot.", "Slowly raise your heel as high as possible, using your calf muscles.", "Pause for a moment at the top, then slowly lower your heel back down.", "Repeat for the desired number of repetitions, then switch to the other leg."]', '["Ponte de pie con los pies separados a la altura de la cadera y sujeta una mancuerna en una mano.", "Levanta un pie del suelo y mantén el equilibrio sobre el otro pie.", "Eleva lentamente el talón lo más alto posible, usando los músculos de la pantorrilla.", "Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta hacia abajo.", "Repite el número de repeticiones deseado, luego cambia a la otra pierna."]'),
  ('Elevación de Gemelo Sentado a 1 Pierna con Mancuerna', 'dumbbell-seated-one-leg-calf-raise.gif', 'lower legs', '["Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your right thigh.", "Extend your left leg straight out in front of you, keeping your foot flexed.", "Place the ball of your right foot on an elevated surface, such as a step or weight plate.", "Using your calf muscles, raise your right heel as high as possible.", "Pause for a moment at the top, then slowly lower your heel back down to the starting position.", "Repeat for the desired number of repetitions, then switch legs."]', '["Siéntate en un banco o silla con los pies apoyados en el suelo y una mancuerna apoyada sobre el muslo derecho.", "Extiende la pierna izquierda recta hacia adelante, manteniendo el pie flexionado.", "Coloca la punta del pie derecho sobre una superficie elevada, como un escalón o un disco de peso.", "Usando los músculos de la pantorrilla, eleva el talón derecho lo más alto posible.", "Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de pierna."]'),
  ('Elevación de Gemelo Sentado a 1 Pierna con Mancuerna (Agarre Neutro)', 'dumbbell-seated-one-leg-calf-raise-hammer-grip.gif', 'lower legs', '["Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your thighs.", "Place one foot on a raised surface, such as a step or block, with your heel hanging off the edge.", "Hold the dumbbell with a hammer grip, meaning your palms are facing each other and your fingers are wrapped around the handle.", "Keeping your core engaged and your back straight, slowly raise your heel as high as possible by pushing through the ball of your foot.", "Pause for a moment at the top, then slowly lower your heel back down to the starting position.", "Repeat for the desired number of repetitions, then switch to the other leg."]', '["Siéntate en un banco o silla con los pies apoyados en el suelo y una mancuerna apoyada sobre los muslos.", "Coloca un pie sobre una superficie elevada, como un escalón o un bloque, con el talón colgando del borde.", "Sujeta la mancuerna con agarre neutro, es decir, con las palmas mirándose entre sí y los dedos envolviendo la barra.", "Manteniendo el core activado y la espalda recta, eleva lentamente el talón lo más alto posible empujando con la punta del pie.", "Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia a la otra pierna."]'),
  ('Elevación de Gemelo Sentado a 1 Pierna con Mancuerna (Palma Arriba)', 'dumbbell-seated-one-leg-calf-raise-palm-up.gif', 'lower legs', '["Sit on a bench or chair with your back straight and your feet flat on the ground.", "Hold a dumbbell in one hand and place it on top of your thigh, palm facing up.", "Lift one leg off the ground and extend it in front of you, keeping your knee slightly bent.", "Raise your heel as high as possible by pushing through the ball of your foot.", "Pause for a moment at the top, then slowly lower your heel back down.", "Repeat for the desired number of repetitions, then switch legs and repeat."]', '["Siéntate en un banco o silla con la espalda recta y los pies apoyados en el suelo.", "Sujeta una mancuerna con una mano y colócala sobre el muslo, con la palma hacia arriba.", "Levanta una pierna del suelo y extiéndela frente a ti, manteniendo la rodilla ligeramente flexionada.", "Eleva el talón lo más alto posible empujando con la punta del pie.", "Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta hacia abajo.", "Repite el número de repeticiones deseado y luego cambia de pierna y repite."]'),
  ('Elevación de Gemelo Sentado a 1 Pierna en Máquina Smith', 'smith-seated-one-leg-calf-raise.gif', 'lower legs', '["Sit on the machine with your back against the pad and your feet on the footrest.", "Place one leg on the footrest and keep the other leg off the footrest.", "Using your calf muscles, raise your heel as high as possible.", "Pause for a moment at the top, then slowly lower your heel back down to the starting position.", "Repeat for the desired number of repetitions, then switch legs and repeat."]', '["Siéntate en la máquina con la espalda contra la almohadilla y los pies sobre el apoyapiés.", "Coloca una pierna sobre el apoyapiés y mantén la otra pierna fuera de él.", "Eleva el talón lo más alto posible, usando los músculos de la pantorrilla.", "Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial.", "Repite el número de repeticiones deseado y luego cambia de pierna y repite."]'),
  ('Elevación de Gemelo tipo Burro a 1 Pierna', 'one-leg-donkey-calf-raise.gif', 'lower legs', '["Stand with your feet shoulder-width apart, toes pointing forward.", "Place your hands on a stable surface for support, such as a wall or a bar.", "Lift one leg off the ground, keeping your knee slightly bent.", "Raise your heel as high as possible, using your calf muscles.", "Pause for a moment at the top, then slowly lower your heel back down.", "Repeat for the desired number of repetitions, then switch legs."]', '["Ponte de pie con los pies separados a la altura de los hombros, con las puntas de los pies apuntando hacia adelante.", "Coloca las manos sobre una superficie estable para apoyarte, como una pared o una barra.", "Levanta una pierna del suelo, manteniendo la rodilla ligeramente flexionada.", "Eleva el talón lo más alto posible, usando los músculos de la pantorrilla.", "Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta hacia abajo.", "Repite el número de repeticiones deseado, luego cambia de pierna."]'),
  ('Elevación de Gemelos Balanceada con Barra', 'barbell-standing-rocking-leg-calf-raise.gif', 'lower legs', '["Stand with your feet shoulder-width apart and hold a barbell across your upper back.", "Raise your heels off the ground as high as possible, balancing on the balls of your feet.", "Slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra sobre la parte superior de la espalda.", "Levanta los talones del suelo lo más alto posible, manteniendo el equilibrio sobre las puntas de los pies.", "Baja lentamente los talones de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Gemelos con Banda Elástica a 2 Piernas', 'band-two-legs-calf-raise-band-under-both-legs-v-2.gif', 'lower legs', '["Stand with your feet shoulder-width apart and place a resistance band under both feet.", "Hold the ends of the band with your hands for stability.", "Raise your heels off the ground as high as possible, using your calves.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y coloca una banda elástica bajo ambos pies.", "Sujeta los extremos de la banda con las manos para mantener el equilibrio.", "Levanta los talones del suelo lo más alto posible, usando las pantorrillas.", "Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Gemelos con Barra en el Suelo', 'barbell-floor-calf-raise.gif', 'lower legs', '["Place a barbell on the floor in front of you.", "Stand with the balls of your feet on the edge of the barbell, with your heels hanging off.", "Hold onto a stable object for balance if needed.", "Raise your heels as high as possible, using your calves to lift your body.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Coloca una barra en el suelo frente a ti.", "Ponte de pie con la parte delantera de los pies sobre el borde de la barra, dejando los talones colgando.", "Sujétate de un objeto estable para mantener el equilibrio si es necesario.", "Levanta los talones lo más alto posible, usando las pantorrillas para elevar el cuerpo.", "Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Gemelos con Barra sobre Escalón', 'barbell-standing-leg-calf-raise.gif', 'lower legs', '["Stand with your feet shoulder-width apart and place a barbell across your upper back.", "Raise your heels off the ground as high as possible, using your calves.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y coloca una barra sobre la parte superior de la espalda.", "Levanta los talones del suelo lo más alto posible, usando las pantorrillas.", "Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Gemelos con Fitball en la Pared', 'exercise-ball-on-the-wall-calf-raise.gif', 'lower legs', '["Stand with your back against a wall and place an exercise ball between your lower back and the wall.", "Position your feet shoulder-width apart, with your toes pointing forward.", "Hold a dumbbell in each hand, with your arms extended by your sides.", "Raise your heels off the ground, lifting your body weight onto the balls of your feet.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con la espalda contra una pared y coloca un balón de ejercicio entre tu zona lumbar y la pared.", "Coloca los pies separados a la altura de los hombros, con la punta de los pies hacia adelante.", "Sujeta una mancuerna en cada mano, con los brazos extendidos a los lados.", "Levanta los talones del suelo, llevando el peso de tu cuerpo hacia la punta de los pies.", "Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Gemelos con Fitball en la Pared (Pelota entre las Rodillas)', 'exercise-ball-on-the-wall-calf-raise-tennis-ball-between-knees.gif', 'lower legs', '["Stand with your back against a wall and place an exercise ball between your lower back and the wall.", "Position your feet shoulder-width apart and slightly in front of you.", "Hold a dumbbell in each hand, with your arms extended by your sides.", "Place a tennis ball between your knees.", "Raise your heels off the ground, lifting your body up onto your toes.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con la espalda contra una pared y coloca un balón de ejercicio entre tu zona lumbar y la pared.", "Coloca los pies separados a la altura de los hombros y ligeramente por delante de ti.", "Sujeta una mancuerna en cada mano, con los brazos extendidos a los lados.", "Coloca una pelota de tenis entre las rodillas.", "Levanta los talones del suelo, elevando el cuerpo sobre la punta de los pies.", "Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Gemelos con Fitball en la Pared (Pelota entre los Tobillos)', 'exercise-ball-on-the-wall-calf-raise-tennis-ball-between-ankles.gif', 'lower legs', '["Stand facing a wall with your feet shoulder-width apart.", "Place an exercise ball between the wall and your lower back.", "Hold a dumbbell in each hand, with your arms extended by your sides.", "Place a tennis ball between your ankles.", "Raise your heels off the ground, lifting your body up onto your toes.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie frente a una pared con los pies separados a la altura de los hombros.", "Coloca un balón de ejercicio entre la pared y tu zona lumbar.", "Sujeta una mancuerna en cada mano, con los brazos extendidos a los lados.", "Coloca una pelota de tenis entre los tobillos.", "Levanta los talones del suelo, elevando el cuerpo sobre la punta de los pies.", "Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Gemelos de Pie con Mancuernas', 'dumbbell-standing-calf-raise.gif', 'lower legs', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.", "Raise your heels off the ground as high as possible, using your calves.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano.", "Levanta los talones del suelo lo más alto posible, usando las pantorrillas.", "Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Gemelos de Pie en Máquina Smith', 'smith-standing-leg-calf-raise.gif', 'lower legs', '["Adjust the smith machine bar to a height that allows you to stand with your feet flat on the ground and your shoulders under the bar.", "Position yourself under the bar with your feet shoulder-width apart and your toes pointing forward.", "Place your hands on the bar for stability.", "Engage your calves and slowly raise your heels off the ground, lifting your body up onto your toes.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la barra de la máquina Smith a una altura que te permita estar de pie con los pies planos sobre el suelo y los hombros debajo de la barra.", "Colócate debajo de la barra con los pies separados a la altura de los hombros y los dedos de los pies apuntando hacia delante.", "Coloca las manos sobre la barra para mayor estabilidad.", "Activa las pantorrillas y levanta lentamente los talones del suelo, elevando el cuerpo sobre la punta de los pies.", "Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Gemelos de Pie en Polea', 'cable-standing-calf-raise.gif', 'lower legs', '["Stand facing a cable machine with your feet shoulder-width apart.", "Hold onto the cable machine handles or attach a cable ankle strap to your ankles.", "Raise your heels off the ground by extending your ankles as high as possible.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.", "Sujétate de los mangos de la máquina de cable o coloca una correa de tobillo de cable en tus tobillos.", "Levanta los talones del suelo extendiendo los tobillos lo más alto posible.", "Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Gemelos de Pie sin Peso', 'bodyweight-standing-calf-raise.gif', 'lower legs', '["Stand with your feet shoulder-width apart, toes pointing forward.", "Place your hands on a wall or stable surface for balance.", "Slowly raise your heels off the ground, lifting your body weight onto the balls of your feet.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, con las puntas de los pies apuntando hacia adelante.", "Coloca las manos sobre una pared o superficie estable para mantener el equilibrio.", "Levanta lentamente los talones del suelo, llevando el peso del cuerpo hacia las puntas de los pies.", "Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Gemelos en Escalera', 'standing-calf-raise-on-a-staircase.gif', 'lower legs', '["Stand on the edge of a step or a sturdy platform with your heels hanging off and your toes on the step.", "Hold onto a railing or wall for balance if needed.", "Slowly raise your heels as high as possible, lifting your body weight onto the balls of your feet.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie en el borde de un escalón o una plataforma firme, con los talones colgando y la punta de los pies sobre el escalón.", "Sujétate de una baranda o pared para mantener el equilibrio si es necesario.", "Levanta lentamente los talones lo más alto posible, elevando el peso de tu cuerpo sobre la punta de los pies.", "Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Gemelos en Máquina Hack', 'hack-calf-raise.gif', 'lower legs', '["Adjust the sled machine to a comfortable weight.", "Stand on the sled machine with your toes on the platform and your heels hanging off.", "Hold onto the handles for stability.", "Raise your heels as high as possible by pushing through the balls of your feet.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la máquina de trineo a un peso adecuado.", "Ponte de pie sobre la máquina de trineo con la punta de los pies en la plataforma y los talones colgando.", "Sujétate de las asas para mantener el equilibrio.", "Levanta los talones lo más alto posible empujando con la punta de los pies.", "Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Gemelos en Máquina Inclinada', 'sled-forward-angled-calf-raise.gif', 'lower legs', '["Adjust the sled machine to a comfortable weight and position yourself on the machine with your toes on the platform and your heels hanging off.", "Place your hands on the handles or the sides of the machine for support.", "Engage your calves and slowly raise your heels as high as possible, pushing against the resistance of the sled.", "Pause for a moment at the top of the movement, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la máquina de trineo a un peso cómodo y colócate en la máquina con la punta de los pies sobre la plataforma y los talones colgando.", "Coloca las manos en las asas o a los lados de la máquina para apoyarte.", "Activa las pantorrillas y eleva lentamente los talones lo más alto posible, empujando contra la resistencia del trineo.", "Haz una pausa breve en la parte alta del movimiento, luego baja lentamente los talones de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Gemelos en Sentadilla en Prensa', 'lever-seated-squat-calf-raise-on-leg-press-machine.gif', 'lower legs', '["Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the footplate.", "Sit on the machine with your back against the backrest and your feet flat on the footplate, shoulder-width apart.", "Place your toes and the balls of your feet on the footplate, keeping your heels off the edge.", "Release the safety handles and push the footplate away from you by extending your knees.", "Once your knees are fully extended, slowly lower your heels by flexing your calves.", "Pause for a moment at the bottom, then push the footplate back up by extending your calves.", "Repeat for the desired number of repetitions."]', '["Ajusta el asiento de la máquina de prensa de piernas de modo que tus rodillas queden ligeramente flexionadas cuando los pies estén sobre la plataforma.", "Siéntate en la máquina con la espalda apoyada en el respaldo y los pies planos sobre la plataforma, separados a la altura de los hombros.", "Coloca los dedos y la planta de los pies sobre la plataforma, manteniendo los talones alejados del borde.", "Suelta las palancas de seguridad y empuja la plataforma alejándola de ti extendiendo las rodillas.", "Una vez que tus rodillas estén completamente extendidas, baja lentamente los talones flexionando las pantorrillas.", "Haz una pausa por un momento en la parte baja y luego empuja la plataforma de nuevo hacia arriba extendiendo las pantorrillas.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Gemelos Sentado con Mancuernas', 'dumbbell-seated-calf-raise.gif', 'lower legs', '["Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your thighs.", "Place the balls of your feet on a raised surface such as a step or block, with your heels hanging off the edge.", "Hold onto the dumbbell for stability.", "Raise your heels as high as possible, lifting your body weight onto the balls of your feet.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco o silla con los pies apoyados en el suelo y una mancuerna apoyada sobre los muslos.", "Coloca la punta de los pies sobre una superficie elevada, como un escalón o un bloque, con los talones colgando del borde.", "Sujétate de la mancuerna para mantener la estabilidad.", "Levanta los talones lo más alto posible, elevando el peso de tu cuerpo sobre las puntas de los pies.", "Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Gemelos Sentado en Máquina', 'lever-seated-calf-raise.gif', 'lower legs', '["Adjust the seat height so that your knees are slightly bent and your feet are flat on the footplate.", "Place your toes on the footplate with your heels hanging off the edge.", "Grasp the handles or the sides of the seat for stability.", "Push through the balls of your feet to raise your heels as high as possible.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura del asiento de modo que las rodillas queden ligeramente flexionadas y los pies queden planos sobre la placa para los pies.", "Coloca los dedos de los pies sobre la placa para los pies, con los talones colgando fuera del borde.", "Sujeta las asas o los lados del asiento para mayor estabilidad.", "Empuja con la parte delantera de los pies para elevar los talones tan alto como sea posible.", "Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Gemelos tipo Burro', 'donkey-calf-raise.gif', 'lower legs', '["Stand with your toes on an elevated surface, such as a step or block.", "Place your hands on a stable support, such as a wall or railing, for balance.", "Raise your heels as high as possible, lifting your body weight onto the balls of your feet.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con las puntas de los pies sobre una superficie elevada, como un escalón o un bloque.", "Coloca las manos en un soporte estable, como una pared o un pasamanos, para mantener el equilibrio.", "Levanta los talones lo más alto posible, elevando el peso de tu cuerpo sobre las puntas de los pies.", "Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Gemelos tipo Burro con Lastre', 'weighted-donkey-calf-raise.gif', 'lower legs', '["Stand on a raised platform with your toes on the edge and your heels hanging off.", "Hold onto a stable object for support.", "Raise your heels as high as possible by extending your ankles.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie sobre una plataforma elevada con la punta de los pies en el borde y los talones colgando.", "Sujétate de un objeto estable para mayor apoyo.", "Eleva los talones tan alto como puedas extendiendo los tobillos.", "Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Gemelos tipo Burro en Máquina', 'lever-donkey-calf-raise-1253.gif', 'lower legs', '["Adjust the leverage machine to the appropriate height for your body.", "Position yourself facing the machine, with your toes on the foot platform and your heels hanging off the edge.", "Place your hands on the handles or the support bars for stability.", "Engage your calves and lift your heels as high as possible, using the balls of your feet.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la máquina de palanca a la altura adecuada para tu cuerpo.", "Colócate de frente a la máquina, con los dedos de los pies en la plataforma y los talones colgando fuera del borde.", "Coloca las manos en las asas o en las barras de soporte para mayor estabilidad.", "Activa las pantorrillas y levanta los talones tan alto como sea posible, usando la parte delantera de los pies.", "Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Puntas en Máquina Smith (Tibial)', 'smith-toe-raise.gif', 'lower legs', '["Adjust the smith machine bar to a height that allows you to comfortably stand with your feet flat on the ground.", "Position yourself under the bar with your shoulders directly below it and your feet shoulder-width apart.", "Place the balls of your feet on a raised platform or weight plates, with your heels hanging off the edge.", "Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.", "Engage your core and keep your back straight throughout the exercise.", "Slowly raise your heels as high as possible, lifting your body weight onto the balls of your feet.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la barra de la máquina Smith a una altura que te permita pararte cómodamente con los pies planos sobre el suelo.", "Colócate debajo de la barra con los hombros justo debajo de ella y los pies separados a la altura de los hombros.", "Coloca la planta de los pies sobre una plataforma elevada o discos de peso, dejando los talones colgando fuera del borde.", "Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros.", "Activa el core y mantén la espalda recta durante todo el ejercicio.", "Levanta lentamente los talones lo más alto posible, elevando el peso de tu cuerpo sobre la punta de los pies.", "Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación Inversa de Gemelo a 1 Pierna con Banda Elástica', 'band-single-leg-reverse-calf-raise.gif', 'lower legs', '["Stand with your feet hip-width apart and place the band around the ball of your foot.", "Hold onto a stable object for balance.", "Slowly raise your heel off the ground, lifting your body weight onto the ball of your foot.", "Pause for a moment at the top, then slowly lower your heel back down to the starting position.", "Repeat for the desired number of repetitions, then switch to the other leg."]', '["Ponte de pie con los pies separados a la altura de las caderas y coloca la banda alrededor de la base de los dedos del pie.", "Sujétate de un objeto estable para mantener el equilibrio.", "Levanta lentamente el talón del suelo, llevando el peso del cuerpo hacia la punta del pie.", "Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia a la otra pierna."]'),
  ('Elevación Inversa de Gemelos en Máquina Smith', 'smith-reverse-calf-raises.gif', 'lower legs', '["Adjust the smith machine bar to a height just below your shoulders.", "Stand facing the bar with your feet hip-width apart and toes pointing forward.", "Place the balls of your feet on the edge of a step or platform, with your heels hanging off.", "Hold onto the bar for support, keeping your back straight and core engaged.", "Raise your heels as high as possible, lifting your body weight onto the balls of your feet.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la barra de la máquina Smith a una altura justo debajo de los hombros.", "Ponte de pie frente a la barra con los pies separados a la altura de la cadera y los dedos de los pies apuntando hacia delante.", "Coloca la punta de los pies en el borde de un escalón o plataforma, con los talones colgando.", "Sujétate de la barra para apoyarte, manteniendo la espalda recta y el core activado.", "Levanta los talones lo más alto posible, elevando el peso de tu cuerpo sobre las puntas de los pies.", "Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Estiramiento Asistido de Gemelos Tumbado', 'assisted-lying-calves-stretch.gif', 'lower legs', '["Lie on your back with your legs extended.", "Bend one knee and place your foot flat on the ground.", "Using your hands or a towel, gently pull your toes towards your body, feeling a stretch in your calf.", "Hold the stretch for 20-30 seconds.", "Release the stretch and repeat on the other leg."]', '["Túmbate sobre tu espalda con las piernas extendidas.", "Flexiona una rodilla y coloca el pie plano sobre el suelo.", "Con las manos o una toalla, jala suavemente los dedos del pie hacia tu cuerpo, sintiendo un estiramiento en la pantorrilla.", "Mantén el estiramiento durante 20-30 segundos.", "Suelta el estiramiento y repite con la otra pierna."]'),
  ('Estiramiento de Gemelo con Cuerda', 'calf-stretch-with-rope.gif', 'lower legs', '["Stand facing a wall or sturdy object with your feet hip-width apart.", "Hold the ends of the rope in each hand and place the middle of the rope around the ball of your right foot.", "Step back with your left foot, keeping your heel on the ground and your leg straight.", "Lean forward, keeping your back straight, and gently pull on the rope to stretch your calf.", "Hold the stretch for 20-30 seconds, then release.", "Repeat on the other leg."]', '["Ponte de pie frente a una pared u objeto firme con los pies separados a la altura de las caderas.", "Sujeta los extremos de la cuerda con cada mano y coloca el centro de la cuerda alrededor de la planta del pie derecho.", "Da un paso atrás con el pie izquierdo, manteniendo el talón en el suelo y la pierna recta.", "Inclínate hacia adelante, manteniendo la espalda recta, y tira suavemente de la cuerda para estirar la pantorrilla.", "Mantén el estiramiento durante 20-30 segundos, luego suelta.", "Repite con la otra pierna."]'),
  ('Estiramiento de Gemelo con Manos en la Pared', 'calf-stretch-with-hands-against-wall.gif', 'lower legs', '["Stand facing a wall with your feet hip-width apart.", "Place your hands against the wall at shoulder height.", "Step your right foot back, keeping your heel on the ground and your leg straight.", "Bend your left knee and lean forward, keeping your back leg straight and your heel on the ground.", "Hold the stretch for 20-30 seconds.", "Switch legs and repeat the stretch."]', '["Ponte de pie frente a una pared con los pies separados a la altura de las caderas.", "Coloca las manos contra la pared a la altura de los hombros.", "Da un paso atrás con el pie derecho, manteniendo el talón en el suelo y la pierna recta.", "Flexiona la rodilla izquierda e inclínate hacia adelante, manteniendo la pierna de atrás recta y el talón en el suelo.", "Mantén el estiramiento durante 20-30 segundos.", "Cambia de pierna y repite el estiramiento."]'),
  ('Estiramiento de Gemelo Empujando la Pared', 'calf-push-stretch-with-hands-against-wall.gif', 'lower legs', '["Stand facing a wall with your feet hip-width apart.", "Place your hands against the wall at shoulder height.", "Step back with one foot, keeping your heel on the ground and your leg straight.", "Bend your front knee slightly and lean forward, feeling a stretch in your calf.", "Hold the stretch for 20-30 seconds.", "Switch legs and repeat the stretch."]', '["Ponte de pie frente a una pared con los pies separados a la altura de las caderas.", "Coloca las manos contra la pared a la altura de los hombros.", "Da un paso atrás con un pie, manteniendo el talón en el suelo y la pierna recta.", "Flexiona ligeramente la rodilla delantera e inclínate hacia adelante, sintiendo un estiramiento en la pantorrilla.", "Mantén el estiramiento durante 20-30 segundos.", "Cambia de pierna y repite el estiramiento."]'),
  ('Estiramiento de Gemelos de Pie con Banco', 'standing-calves-calf-stretch.gif', 'lower legs', '["Stand facing a wall or sturdy object, about an arm''s length away.", "Place your hands on the wall or object at shoulder height.", "Step back with one foot, keeping your heel flat on the ground.", "Bend your front knee slightly and lean forward, keeping your back leg straight.", "You should feel a stretch in your calf muscle.", "Hold the stretch for 20-30 seconds.", "Repeat on the other leg."]', '["Ponte de pie frente a una pared u objeto firme, a una distancia aproximada de un brazo.", "Coloca las manos sobre la pared o el objeto a la altura de los hombros.", "Da un paso hacia atrás con un pie, manteniendo el talón plano sobre el suelo.", "Flexiona ligeramente la rodilla delantera e inclínate hacia adelante, manteniendo la pierna trasera recta.", "Deberías sentir un estiramiento en el músculo de la pantorrilla.", "Mantén el estiramiento durante 20-30 segundos.", "Repite con la otra pierna."]'),
  ('Estiramiento de Gemelos de Pie en la Pared', 'standing-calves.gif', 'lower legs', '["Stand with your feet shoulder-width apart, toes pointing forward.", "Raise your heels off the ground as high as possible, standing on your toes.", "Hold the position for a moment, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, con las puntas de los pies apuntando hacia adelante.", "Levanta los talones del suelo lo más alto posible, apoyándote sobre la punta de los pies.", "Mantén la posición por un momento y luego baja lentamente los talones de nuevo a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Estiramiento de Gemelos Sentado', 'seated-calf-stretch-male.gif', 'lower legs', '["Sit on the edge of a chair or bench with your feet flat on the ground.", "Extend one leg straight out in front of you, keeping your heel on the ground.", "Lean forward slightly, feeling a stretch in your calf muscle.", "Hold the stretch for 20-30 seconds.", "Switch legs and repeat the stretch."]', '["Siéntate en el borde de una silla o banco con los pies planos sobre el suelo.", "Extiende una pierna recta frente a ti, manteniendo el talón en el suelo.", "Inclínate ligeramente hacia delante, sintiendo un estiramiento en la pantorrilla.", "Mantén el estiramiento durante 20-30 segundos.", "Cambia de pierna y repite el estiramiento."]'),
  ('Estiramiento de Peroneos', 'peroneals-stretch.gif', 'lower legs', '["Sit on the ground with your legs extended in front of you.", "Loop the rope around the ball of your foot and hold the ends of the rope with your hands.", "Gently pull the rope towards you, flexing your foot and stretching your calf muscles.", "Hold the stretch for 15-30 seconds.", "Release the tension on the rope and repeat the stretch on the other leg.", "Repeat for the desired number of repetitions."]', '["Siéntate en el suelo con las piernas extendidas frente a ti.", "Enrolla la cuerda alrededor de la planta del pie y sujeta los extremos de la cuerda con las manos.", "Tira suavemente de la cuerda hacia ti, flexionando el pie y estirando los músculos de la pantorrilla.", "Mantén el estiramiento durante 15-30 segundos.", "Suelta la tensión de la cuerda y repite el estiramiento en la otra pierna.", "Repite el número de repeticiones deseado."]'),
  ('Estiramiento de Tibial Posterior', 'posterior-tibialis-stretch.gif', 'lower legs', '["Sit on the ground with your legs extended in front of you.", "Loop the rope around the ball of your foot and hold the ends of the rope with your hands.", "Gently pull the rope towards you, flexing your foot and stretching your calf muscles.", "Hold the stretch for 20-30 seconds.", "Release the tension on the rope and relax your foot.", "Repeat the stretch on the other leg."]', '["Siéntate en el suelo con las piernas extendidas frente a ti.", "Enrolla la cuerda alrededor de la planta del pie y sujeta los extremos de la cuerda con las manos.", "Tira suavemente de la cuerda hacia ti, flexionando el pie y estirando los músculos de la pantorrilla.", "Mantén el estiramiento durante 20-30 segundos.", "Suelta la tensión de la cuerda y relaja el pie.", "Repite el estiramiento en la otra pierna."]'),
  ('Gemelos en Máquina Rotatoria', 'lever-rotary-calf.gif', 'lower legs', '["Adjust the seat height so that your knees are slightly bent and your feet are flat on the footplate.", "Place your toes on the footplate, with your heels hanging off the edge.", "Grasp the handles or the sides of the machine for stability.", "Push through the balls of your feet, raising your heels as high as possible.", "Pause for a moment at the top, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura del asiento de modo que las rodillas queden ligeramente flexionadas y los pies queden planos sobre la placa para los pies.", "Coloca los dedos de los pies sobre la placa para los pies, con los talones colgando fuera del borde.", "Sujeta las asas o los lados de la máquina para mayor estabilidad.", "Empuja con la parte delantera de los pies, elevando los talones tan alto como sea posible.", "Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Prensa de Gemelos en Máquina', 'lever-calf-press.gif', 'lower legs', '["Adjust the seat of the leverage machine so that your shoulders are aligned with the lever pad.", "Place your toes on the lever pad, with your heels hanging off the edge.", "Grasp the handles or side supports for stability.", "Push the lever pad down by extending your ankles, contracting your calf muscles.", "Pause for a moment at the bottom of the movement.", "Slowly return to the starting position by allowing your heels to rise back up.", "Repeat for the desired number of repetitions."]', '["Ajusta el asiento de la máquina de palanca de modo que los hombros queden alineados con la almohadilla de la palanca.", "Coloca los dedos de los pies sobre la almohadilla de la palanca, con los talones colgando fuera del borde.", "Sujeta las asas o los soportes laterales para mayor estabilidad.", "Empuja la almohadilla de la palanca hacia abajo extendiendo los tobillos, contrayendo los músculos de las pantorrillas.", "Haz una pausa por un momento en la parte baja del movimiento.", "Vuelve lentamente a la posición inicial dejando que los talones se eleven de nuevo.", "Repite el número de repeticiones deseado."]'),
  ('Prensa de Gemelos Sentado en Máquina', 'lever-seated-calf-press.gif', 'lower legs', '["Adjust the seat of the machine so that your shoulders are aligned with the lever pad.", "Place your toes on the lower portion of the platform and position your knees under the lever pad.", "Grasp the handles on the sides of the seat for stability.", "Press the lever pad down by extending your ankles, lifting your heels as high as possible.", "Pause for a moment at the top of the movement, then slowly lower your heels back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta el asiento de la máquina de modo que los hombros queden alineados con la almohadilla de la palanca.", "Coloca los dedos de los pies en la parte inferior de la plataforma y posiciona las rodillas debajo de la almohadilla de la palanca.", "Sujeta las asas a los lados del asiento para mayor estabilidad.", "Presiona la almohadilla de la palanca hacia abajo extendiendo los tobillos, elevando los talones tan alto como sea posible.", "Haz una pausa breve en la parte alta del movimiento, luego baja lentamente los talones de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Prensa de Gemelos Tumbado', 'sled-lying-calf-press.gif', 'lower legs', '["Adjust the sled machine to a comfortable weight.", "Sit on the sled machine with your back against the pad and your feet on the platform.", "Place your toes and the balls of your feet on the edge of the platform, with your heels hanging off.", "Push the platform away from you by extending your ankles, keeping your knees slightly bent.", "Continue pushing until your calves are fully contracted.", "Hold the contraction for a moment, then slowly lower the platform back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la máquina de trineo a un peso adecuado.", "Siéntate en la máquina de trineo con la espalda contra el respaldo y los pies sobre la plataforma.", "Coloca la punta y la almohadilla de los pies en el borde de la plataforma, con los talones colgando.", "Empuja la plataforma alejándola de ti extendiendo los tobillos, manteniendo las rodillas ligeramente flexionadas.", "Continúa empujando hasta que las pantorrillas estén completamente contraídas.", "Mantén la contracción por un momento, luego baja lentamente la plataforma de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Salto desde Banco con Estabilización a 1 Pierna', 'box-jump-down-with-one-leg-stabilization.gif', 'lower legs', '["Stand in front of a box or platform with your feet shoulder-width apart.", "Bend your knees and jump onto the box, landing softly with one foot on the box and the other foot hanging off the edge.", "Stabilize yourself on the box with the foot that is on it, while keeping the other foot off the ground.", "Hold this position for a few seconds, engaging your calf muscles to maintain balance.", "Slowly step down with the foot that is on the box, returning to the starting position.", "Repeat the exercise with the other leg."]', '["Ponte de pie frente a una caja o plataforma con los pies separados a la altura de los hombros.", "Flexiona las rodillas y salta sobre la caja, aterrizando suavemente con un pie sobre la caja y el otro pie colgando del borde.", "Estabilízate sobre la caja con el pie que está sobre ella, mientras mantienes el otro pie fuera del suelo.", "Mantén esta posición durante unos segundos, activando los músculos de la pantorrilla para conservar el equilibrio.", "Baja lentamente con el pie que está sobre la caja, volviendo a la posición inicial.", "Repite el ejercicio con la otra pierna."]'),
  ('Estiramiento de Cuello con Empuje Lateral', 'side-push-neck-stretch.gif', 'neck', '["Stand or sit up straight with your shoulders relaxed.", "Tilt your head to the right, bringing your right ear towards your right shoulder.", "Place your right hand on the left side of your head and gently apply pressure to increase the stretch.", "Hold the stretch for 15-30 seconds.", "Repeat on the other side, tilting your head to the left and applying pressure with your left hand.", "Repeat the stretch 2-3 times on each side."]', '["Ponte de pie o siéntate erguido con los hombros relajados.", "Inclina la cabeza hacia la derecha, llevando la oreja derecha hacia el hombro derecho.", "Coloca la mano derecha en el lado izquierdo de la cabeza y aplica una presión suave para aumentar el estiramiento.", "Mantén el estiramiento durante 15-30 segundos.", "Repite hacia el otro lado, inclinando la cabeza hacia la izquierda y aplicando presión con la mano izquierda.", "Repite el estiramiento 2-3 veces en cada lado."]'),
  ('Estiramiento Lateral de Cuello', 'neck-side-stretch.gif', 'neck', '["Stand or sit up straight with your shoulders relaxed.", "Tilt your head to one side, bringing your ear towards your shoulder.", "Hold the stretch for 15-30 seconds.", "Repeat on the other side.", "Perform 2-4 sets on each side."]', '["Ponte de pie o siéntate erguido con los hombros relajados.", "Inclina la cabeza hacia un lado, llevando la oreja hacia el hombro.", "Mantén el estiramiento durante 15-30 segundos.", "Repite del otro lado.", "Realiza de 2 a 4 series por cada lado."]'),
  ('Apertura Inversa a 1 Brazo con Mancuerna y Apoyo', 'dumbbell-one-arm-reverse-fly-with-support.gif', 'shoulders', '["Sit on a bench with your feet flat on the ground and your back straight.", "Hold a dumbbell in one hand with your palm facing inwards.", "Lean forward and place your free hand on the bench for support.", "Keep your arm slightly bent and raise it out to the side until it is parallel to the ground.", "Pause for a moment at the top, then slowly lower your arm back down to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Siéntate en un banco con los pies apoyados planos en el suelo y la espalda recta.", "Sostén una mancuerna en una mano con la palma hacia adentro.", "Inclínate hacia adelante y coloca la mano libre sobre el banco para apoyarte.", "Mantén el brazo ligeramente flexionado y levántalo hacia el lado hasta que quede paralelo al suelo.", "Haz una pausa breve en la parte más alta, luego baja lentamente el brazo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Aperturas Inversas Altas en Polea Cruzada', 'cable-standing-cross-over-high-reverse-fly.gif', 'shoulders', '["Attach a D-handle to each side of a cable machine at shoulder height.", "Stand in the middle of the cable machine with your feet shoulder-width apart.", "Grasp the handles with an overhand grip and extend your arms out to the sides, palms facing forward.", "Keep a slight bend in your elbows and maintain a straight back throughout the exercise.", "Engage your shoulder muscles and squeeze your shoulder blades together as you pull the handles towards the front of your body.", "Pause for a moment at the peak of the movement, then slowly return to the starting position.", "Repeat for the desired number of repetitions."]', '["Coloca un mango en D en cada lado de una máquina de cable a la altura de los hombros.", "Ponte de pie en el medio de la máquina de cable con los pies separados a la altura de los hombros.", "Agarra los mangos con un agarre prono y extiende los brazos hacia los lados, con las palmas hacia adelante.", "Mantén una ligera flexión en los codos y conserva la espalda recta durante todo el ejercicio.", "Activa los músculos de los hombros y aprieta los omóplatos entre sí mientras tiras de los mangos hacia la parte delantera de tu cuerpo.", "Haz una pausa breve en el punto máximo del movimiento, luego regresa lentamente a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Aperturas Inversas con Banda Elástica', 'band-reverse-fly.gif', 'shoulders', '["Attach the band to a stationary object at chest height.", "Stand with your feet shoulder-width apart and hold the band with both hands in front of you.", "Keep your arms straight and lift them out to the sides until they are parallel to the ground.", "Squeeze your shoulder blades together at the top of the movement.", "Slowly lower your arms back to the starting position.", "Repeat for the desired number of repetitions."]', '["Sujeta la banda a un objeto fijo a la altura del pecho.", "Ponte de pie con los pies separados a la altura de los hombros y sostén la banda con ambas manos frente a ti.", "Mantén los brazos rectos y levántalos hacia los lados hasta que queden paralelos al suelo.", "Junta los omóplatos en la parte superior del movimiento.", "Baja lentamente los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Aperturas Inversas con Mancuernas en Banco Inclinado', 'dumbbell-reverse-fly.gif', 'shoulders', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Extend your arms straight down in front of you, palms facing each other.", "Keeping a slight bend in your elbows, raise your arms out to the sides until they are parallel to the ground.", "Pause for a moment at the top, then slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano.", "Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.", "Extiende los brazos rectos hacia adelante, con las palmas mirándose entre sí.", "Manteniendo una ligera flexión en los codos, levanta los brazos hacia los lados hasta que queden paralelos al suelo.", "Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Aperturas Inversas con Rotación con Mancuernas en Banco Inclinado', 'dumbbell-rotation-reverse-fly.gif', 'shoulders', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing inwards.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.", "Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor.", "Rotate your arms so that your palms are facing downwards.", "Slowly lower your arms back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adentro.", "Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado.", "Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo.", "Gira los brazos de modo que las palmas queden mirando hacia abajo.", "Baja lentamente los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Aperturas Inversas en Máquina', 'lever-seated-reverse-fly.gif', 'shoulders', '["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.", "Grasp the handles with an overhand grip and keep your arms slightly bent.", "Exhale and squeeze your shoulder blades together as you pull the handles back and outward, away from your body.", "Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura del asiento y colócate en la máquina con el pecho contra la almohadilla y los pies planos en el suelo.", "Agarra las asas con un agarre prono y mantén los brazos ligeramente flexionados.", "Exhala y junta las escápulas mientras llevas las asas hacia atrás y hacia afuera, alejándolas de tu cuerpo.", "Haz una pausa breve en el punto máximo de contracción, luego inhala y vuelve lentamente a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Aperturas Inversas en Máquina con Agarre Neutro', 'lever-seated-reverse-fly-parallel-grip.gif', 'shoulders', '["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.", "Grasp the handles with a parallel grip, palms facing each other, and keep your arms slightly bent.", "Exhale and squeeze your shoulder blades together as you pull the handles back and outward, away from your body.", "Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura del asiento y colócate en la máquina con el pecho contra la almohadilla y los pies planos en el suelo.", "Agarra las asas con un agarre paralelo, con las palmas enfrentadas, y mantén los brazos ligeramente flexionados.", "Exhala y junta las escápulas mientras llevas las asas hacia atrás y hacia afuera, alejándolas de tu cuerpo.", "Haz una pausa breve en el punto máximo de contracción, luego inhala y vuelve lentamente a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Aperturas Inversas Inclinado en Polea Cruzada', 'cable-cross-over-revers-fly.gif', 'shoulders', '["Attach a D-handle to each low pulley cable and stand in the middle of the cable crossover machine.", "Grasp the handles with a pronated grip (palms facing down) and take a step forward, positioning your feet shoulder-width apart.", "Bend your knees slightly and lean forward at the waist, keeping your back straight and your abs engaged.", "With your arms extended out to the sides and slightly bent at the elbows, exhale and squeeze your shoulder blades together as you pull the cables back and upward in a reverse fly motion.", "Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.", "Repeat for the desired number of repetitions."]', '["Coloca una agarradera en D en cada cable de polea baja y ponte de pie en el centro de la máquina de cable cruzado.", "Sujeta las agarraderas con agarre prono (palmas hacia abajo) y da un paso hacia adelante, colocando los pies separados a la altura de los hombros.", "Flexiona ligeramente las rodillas e inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el abdomen activado.", "Con los brazos extendidos hacia los lados y ligeramente flexionados en los codos, exhala y junta los omóplatos mientras tiras de los cables hacia atrás y hacia arriba en un movimiento de apertura inversa.", "Haz una pausa breve en el punto máximo de contracción, luego inhala y vuelve lentamente a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Aperturas Inversas Tumbado en Polea', 'cable-supine-reverse-fly.gif', 'shoulders', '["Attach a D-handle to a low pulley cable machine and lie face down on a flat bench.", "Grasp the D-handle with each hand, palms facing down, and extend your arms straight out in front of you.", "Keeping your arms straight, raise them out to the sides until they are parallel to the floor.", "Pause for a moment at the top, then slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Coloca un mango en D en una máquina de cable con polea baja y túmbate boca abajo en un banco plano.", "Agarra el mango en D con cada mano, con las palmas hacia abajo, y extiende los brazos frente a ti.", "Manteniendo los brazos rectos, levántalos hacia los lados hasta que estén paralelos al suelo.", "Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Aperturas Posteriores Sentado con Mancuernas', 'dumbbell-rear-fly.gif', 'shoulders', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Extend your arms straight down towards the ground, palms facing each other.", "Keeping a slight bend in your elbows, lift your arms out to the sides and squeeze your shoulder blades together.", "Pause for a moment at the top, then slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano.", "Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.", "Extiende los brazos rectos hacia el suelo, con las palmas mirándose entre sí.", "Manteniendo una ligera flexión en los codos, levanta los brazos hacia los lados y aprieta los omóplatos entre sí.", "Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Arrancada a 1 Brazo con Barra', 'barbell-one-arm-snatch.gif', 'shoulders', '["Stand with your feet shoulder-width apart, toes pointing slightly outwards.", "Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.", "Bend your knees and lower your hips into a squat position, keeping your back straight and chest up.", "Explosively extend your hips, knees, and ankles, driving the barbell upwards.", "As the barbell reaches chest level, pull it upwards with your arm, keeping it close to your body.", "Rotate your elbow under the barbell and extend your arm fully overhead, locking out your elbow.", "Lower the barbell back down to the starting position in a controlled manner.", "Repeat for the desired number of repetitions, then switch arms."]', '["Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera.", "Sujeta la barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros.", "Flexiona las rodillas y baja las caderas hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.", "Extiende las caderas, las rodillas y los tobillos de forma explosiva, impulsando la barra hacia arriba.", "Cuando la barra llegue a la altura del pecho, tira de ella hacia arriba con el brazo, manteniéndola cerca del cuerpo.", "Rota el codo por debajo de la barra y extiende el brazo completamente por encima de la cabeza, bloqueando el codo.", "Baja la barra de vuelta a la posición inicial de forma controlada.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Arrancada a 1 Brazo con Kettlebell', 'kettlebell-one-arm-snatch.gif', 'shoulders', '["Stand with your feet shoulder-width apart, holding a kettlebell in one hand between your legs.", "Bend your knees slightly and hinge at the hips, lowering the kettlebell towards the ground.", "Explosively extend your hips and knees, using the momentum to swing the kettlebell up towards your shoulder.", "As the kettlebell reaches shoulder height, rotate your hand and punch it straight up overhead, fully extending your arm.", "Lower the kettlebell back down between your legs and repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano entre las piernas.", "Flexiona ligeramente las rodillas e inclínate desde las caderas, bajando la pesa rusa hacia el suelo.", "Extiende explosivamente las caderas y las rodillas, usando el impulso para hacer que la pesa rusa suba hacia el hombro.", "Cuando la pesa rusa llegue a la altura del hombro, rota la mano y lánzala recta hacia arriba por encima de la cabeza, extendiendo el brazo por completo.", "Baja la pesa rusa de vuelta entre las piernas y repite el número de repeticiones deseado."]'),
  ('Arrancada Doble con Kettlebells', 'kettlebell-double-snatch.gif', 'shoulders', '["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at arm''s length in front of your thighs.", "Bend your knees slightly and hinge forward at the hips, keeping your back flat and chest up.", "In one explosive motion, extend your hips, knees, and ankles, and simultaneously pull the kettlebells up towards your shoulders.", "As the kettlebells reach shoulder level, rotate your wrists and punch the kettlebells overhead, fully extending your arms.", "Lower the kettlebells back down to the starting position and repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa en cada mano con el brazo extendido frente a los muslos.", "Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado.", "En un solo movimiento explosivo, extiende las caderas, las rodillas y los tobillos, y al mismo tiempo tira de las pesas rusas hacia los hombros.", "Cuando las pesas rusas lleguen a la altura del hombro, rota las muñecas y lanza las pesas rusas por encima de la cabeza, extendiendo los brazos por completo.", "Baja las pesas rusas de vuelta a la posición inicial y repite el número de repeticiones deseado."]'),
  ('Cargada con 2 Kettlebells', 'kettlebell-two-arm-clean.gif', 'shoulders', '["Stand with your feet shoulder-width apart, holding a kettlebell in front of your thighs with both hands, palms facing towards you.", "Bend your knees slightly and hinge at the hips, lowering the kettlebell towards the ground.", "Explosively extend your hips and knees, using the momentum to pull the kettlebell up towards your shoulders.", "As the kettlebell reaches shoulder height, rotate your wrists and catch the kettlebell in the rack position, with your elbows tucked in and the kettlebell resting on the back of your forearm.", "Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente a los muslos con ambas manos, con las palmas hacia ti.", "Flexiona ligeramente las rodillas e inclínate desde las caderas, bajando la pesa rusa hacia el suelo.", "Extiende explosivamente las caderas y las rodillas, usando el impulso para tirar de la pesa rusa hacia los hombros.", "Cuando la pesa rusa llegue a la altura del hombro, rota las muñecas y atrápala en posición de descanso, con los codos pegados al cuerpo y la pesa rusa apoyada en la parte posterior del antebrazo.", "Baja la pesa rusa de vuelta a la posición inicial y repite el número de repeticiones deseado."]'),
  ('Cargada y Jerk a 1 Brazo con Kettlebell', 'kettlebell-one-arm-clean-and-jerk.gif', 'shoulders', '["Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.", "Bend your knees slightly and hinge at the hips, lowering the kettlebell between your legs.", "Explosively extend your hips, knees, and ankles, using the momentum to swing the kettlebell up to shoulder height.", "As the kettlebell reaches shoulder height, rotate your wrist and punch your hand straight up, locking out your arm overhead.", "Lower the kettlebell back down to the starting position and repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano en agarre prono.", "Flexiona ligeramente las rodillas y inclínate desde las caderas, bajando la pesa rusa entre las piernas.", "Extiende explosivamente las caderas, las rodillas y los tobillos, usando el impulso para hacer que la pesa rusa suba hasta la altura del hombro.", "Cuando la pesa rusa llegue a la altura del hombro, rota la muñeca y lanza la mano recta hacia arriba, bloqueando el brazo por encima de la cabeza.", "Baja la pesa rusa de vuelta a la posición inicial y repite el número de repeticiones deseado."]'),
  ('Cruz de Hierro con Mancuernas', 'dumbbell-iron-cross.gif', 'shoulders', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.", "Raise your arms out to the sides until they are parallel to the ground, forming a T shape with your body.", "Pause for a moment, then slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a los costados.", "Levanta los brazos hacia los lados hasta que queden paralelos al suelo, formando una T con el cuerpo.", "Haz una pausa por un momento, luego baja lentamente los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Cuerdas de Batalla (Battle Ropes)', 'battling-ropes.gif', 'shoulders', '["Stand with your feet shoulder-width apart and knees slightly bent.", "Hold one end of the rope in each hand, with your palms facing each other.", "Raise your arms to shoulder height, keeping your elbows slightly bent.", "Begin making alternating waves with the ropes by rapidly raising and lowering each arm.", "Continue for the desired duration or number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.", "Sujeta un extremo de la cuerda en cada mano, con las palmas mirándose entre sí.", "Levanta los brazos hasta la altura de los hombros, manteniendo los codos ligeramente flexionados.", "Comienza a hacer ondas alternas con las cuerdas, levantando y bajando rápidamente cada brazo.", "Continúa durante el tiempo o el número de repeticiones deseado."]'),
  ('Círculos con Disco', 'weighted-round-arm.gif', 'shoulders', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Raise your arms out to the sides, keeping a slight bend in your elbows.", "Continue lifting your arms until they are parallel to the ground.", "Pause for a moment at the top, then slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano.", "Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.", "Eleva los brazos hacia los lados, manteniendo una ligera flexión en los codos.", "Continúa elevando los brazos hasta que queden paralelos al suelo.", "Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevaciones Laterales con Polea Doble', 'cable-lateral-raise.gif', 'shoulders', '["Stand with your feet shoulder-width apart and grasp the cable handles with an overhand grip.", "Keep your arms straight and your core engaged.", "Raise your arms out to the sides until they are parallel to the floor.", "Pause for a moment at the top, then slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta las agarraderas del cable con un agarre prono.", "Mantén los brazos rectos y el core activado.", "Levanta los brazos hacia los lados hasta que queden paralelos al suelo.", "Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Deltoides Posterior con Barra', 'barbell-rear-delt-raise.gif', 'shoulders', '["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Raise the barbell out to the sides, keeping your arms straight, until they are parallel to the ground.", "Pause for a moment at the top, then slowly lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre pronado, con las palmas hacia abajo.", "Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.", "Levanta la barra hacia los lados, manteniendo los brazos rectos, hasta que queden paralelos al suelo.", "Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Deltoides Posterior de Pie con Mancuernas', 'dumbbell-rear-delt-raise.gif', 'shoulders', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor.", "Pause for a moment at the top, then slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano, con las palmas hacia el cuerpo.", "Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.", "Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo.", "Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación en T con Mancuernas en Banco Inclinado', 'dumbbell-incline-t-raise.gif', 'shoulders', '["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing inwards.", "Lean forward and let your arms hang straight down, perpendicular to the floor.", "Keeping your arms straight, raise them out to the sides until they are parallel to the floor, forming a ''T'' shape with your body.", "Pause for a moment at the top, then slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta un banco inclinado a un ángulo de 45 grados y siéntate en él con una mancuerna en cada mano, con las palmas hacia adentro.", "Inclínate hacia adelante y deja que los brazos cuelguen rectos hacia abajo, perpendiculares al suelo.", "Manteniendo los brazos rectos, levántalos hacia los lados hasta que queden paralelos al suelo, formando una ''T'' con el cuerpo.", "Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación en Y con Banda Elástica', 'band-y-raise.gif', 'shoulders', '["Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing inwards.", "Keep your arms straight and lift them up and out to the sides, forming a ''Y'' shape with your body.", "Squeeze your shoulder blades together at the top of the movement.", "Slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta la banda frente a los muslos con las palmas mirando hacia adentro.", "Mantén los brazos rectos y levántalos hacia arriba y hacia los lados, formando una ''Y'' con el cuerpo.", "Junta los omóplatos en la parte superior del movimiento.", "Baja lentamente los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación Frontal Alterna de Pie con Mancuernas', 'dumbbell-standing-alternate-raise.gif', 'shoulders', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.", "Keep your back straight and your core engaged.", "Raise one dumbbell to the side, keeping your arm straight and your palm facing down.", "Continue lifting until your arm is parallel to the ground.", "Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.", "Repeat with the other arm.", "Alternate between arms for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia el cuerpo.", "Mantén la espalda recta y el core activado.", "Levanta una mancuerna hacia el lado, manteniendo el brazo recto y la palma hacia abajo.", "Continúa levantando hasta que el brazo quede paralelo al suelo.", "Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite con el otro brazo.", "Alterna entre los brazos el número de repeticiones deseado."]'),
  ('Elevación Frontal Alterna Sentado con Mancuernas', 'dumbbell-seated-alternate-front-raise.gif', 'shoulders', '["Sit on a bench with your back straight and feet flat on the ground.", "Hold a dumbbell in each hand with your palms facing your body and arms extended down by your sides.", "Keeping your arms straight, raise one dumbbell in front of you until it is parallel to the ground.", "Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.", "Repeat with the other arm.", "Alternate between arms for the desired number of repetitions."]', '["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.", "Sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo y los brazos extendidos hacia abajo a los lados.", "Manteniendo los brazos rectos, levanta una mancuerna frente a ti hasta que quede paralela al suelo.", "Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite con el otro brazo.", "Alterna entre los brazos el número de repeticiones deseado."]'),
  ('Elevación Frontal con Barra', 'barbell-front-raise.gif', 'shoulders', '["Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip.", "Keep your arms straight and lift the barbell forward and upward until it reaches shoulder level.", "Pause for a moment at the top, then slowly lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra frente a los muslos con un agarre pronado.", "Mantén los brazos rectos y levanta la barra hacia delante y hacia arriba hasta que alcance la altura de los hombros.", "Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación Frontal con Disco', 'weighted-front-raise.gif', 'shoulders', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.", "Keeping your arms straight, exhale and lift the dumbbells in front of you until they are at shoulder level.", "Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia los muslos.", "Manteniendo los brazos rectos, exhala y levanta las mancuernas frente a ti hasta que queden a la altura de los hombros.", "Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación Frontal con Mancuernas', 'dumbbell-front-raise.gif', 'shoulders', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.", "Keeping your arms straight, exhale and lift the dumbbells in front of you until they are at shoulder level.", "Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia los muslos.", "Manteniendo los brazos rectos, exhala y levanta las mancuernas frente a ti hasta que queden a la altura de los hombros.", "Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación Frontal con Polea Doble', 'cable-front-shoulder-raise.gif', 'shoulders', '["Stand with your feet shoulder-width apart and grasp the cable handle with an overhand grip.", "Keep your back straight and your core engaged.", "Raise the cable handle in front of you, keeping your arms straight and your palms facing down.", "Continue lifting until your arms are parallel to the floor.", "Pause for a moment at the top, then slowly lower the cable handle back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta la agarradera del cable con agarre prono.", "Mantén la espalda recta y el core activado.", "Levanta la agarradera del cable frente a ti, manteniendo los brazos rectos y las palmas hacia abajo.", "Continúa levantando hasta que los brazos queden paralelos al suelo.", "Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación Frontal en Polea', 'cable-front-raise.gif', 'shoulders', '["Stand with your feet shoulder-width apart and grasp the cable handle with an overhand grip.", "Keep your back straight and your core engaged.", "Raise the cable handle in front of you, keeping your arms straight and your palms facing down.", "Continue lifting until your arms are parallel to the floor.", "Pause for a moment at the top, then slowly lower the cable handle back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta la agarradera del cable con agarre prono.", "Mantén la espalda recta y el core activado.", "Levanta la agarradera del cable frente a ti, manteniendo los brazos rectos y las palmas hacia abajo.", "Continúa levantando hasta que los brazos queden paralelos al suelo.", "Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación Frontal en Polea desde Atrás', 'cable-forward-raise.gif', 'shoulders', '["Stand with your feet shoulder-width apart and your knees slightly bent.", "Hold the cable handle with an overhand grip, palms facing down, and your arms fully extended in front of you.", "Keeping your arms straight, raise the cable handle up to shoulder level.", "Pause for a moment at the top, then slowly lower the cable handle back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.", "Sujeta la agarradera del cable con agarre prono, palmas hacia abajo, y los brazos completamente extendidos frente a ti.", "Manteniendo los brazos rectos, levanta la agarradera del cable hasta la altura de los hombros.", "Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación Frontal por Encima de la Cabeza con Barra', 'barbell-standing-front-raise-over-head.gif', 'shoulders', '["Stand with your feet shoulder-width apart, holding a barbell in front of your thighs with an overhand grip.", "Keep your back straight and engage your core.", "Slowly raise the barbell in front of you, keeping your arms straight and your palms facing down.", "Continue lifting until the barbell is slightly above shoulder level.", "Pause for a moment at the top, then slowly lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una barra frente a los muslos con agarre prono.", "Mantén la espalda recta y activa el core.", "Levanta lentamente la barra frente a ti, manteniendo los brazos rectos y las palmas hacia abajo.", "Continúa levantando hasta que la barra quede ligeramente por encima del nivel de los hombros.", "Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación Frontal por Encima de la Cabeza con Mancuerna', 'dumbbell-standing-front-raise-above-head.gif', 'shoulders', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.", "Keep your arms straight and lift the dumbbells in front of you, raising them above your head.", "Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono.", "Mantén los brazos rectos y levanta las mancuernas frente a ti, elevándolas por encima de la cabeza.", "Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación Frontal Sentado con Mancuernas', 'dumbbell-seated-front-raise.gif', 'shoulders', '["Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs.", "Keep your back straight and core engaged.", "Raise the dumbbells in front of you, with your palms facing down, until they are at shoulder level.", "Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco con los pies apoyados en el suelo y una mancuerna en cada mano, apoyadas sobre los muslos.", "Mantén la espalda recta y el core activado.", "Levanta las mancuernas frente a ti, con las palmas hacia abajo, hasta que queden a la altura de los hombros.", "Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación Frontal-Lateral con Banda Elástica', 'band-front-lateral-raise.gif', 'shoulders', '["Stand with your feet shoulder-width apart and hold the band in front of your thighs with your palms facing down.", "Keep your arms straight and lift the band up in front of you until your arms are parallel to the ground.", "Pause for a moment at the top, then slowly lower the band back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sostén la banda frente a los muslos con las palmas hacia abajo.", "Mantén los brazos rectos y levanta la banda frente a ti hasta que los brazos queden paralelos al suelo.", "Haz una pausa por un momento en la parte superior, luego baja lentamente la banda de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación Lateral a 1 Brazo con Mancuerna', 'dumbbell-one-arm-lateral-raise.gif', 'shoulders', '["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing your body.", "Keep your back straight and your core engaged throughout the exercise.", "Raise the dumbbell to the side, keeping your arm straight and your palm facing down.", "Continue lifting until your arm is parallel to the ground.", "Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."]', '["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en una mano con la palma hacia el cuerpo.", "Mantén la espalda recta y el core activado durante todo el ejercicio.", "Levanta la mancuerna hacia el lado, manteniendo el brazo recto y la palma hacia abajo.", "Continúa levantando hasta que el brazo quede paralelo al suelo.", "Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia al otro brazo."]'),
  ('Elevación Lateral a 1 Brazo con Mancuerna y Apoyo', 'dumbbell-one-arm-lateral-raise-with-support.gif', 'shoulders', '["Stand with your feet shoulder-width apart and hold a dumbbell in one hand, with your palm facing your body.", "Place your other hand on a stable surface, such as a bench or wall, for support.", "Keep your back straight and engage your core.", "Raise the dumbbell out to the side, keeping your arm straight and your palm facing down.", "Continue lifting until your arm is parallel to the ground.", "Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.", "Repeat for the desired number of repetitions, then switch sides."]', '["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en una mano, con la palma hacia el cuerpo.", "Coloca la otra mano sobre una superficie estable, como un banco o una pared, para apoyarte.", "Mantén la espalda recta y activa el core.", "Levanta la mancuerna hacia el lado, manteniendo el brazo recto y la palma hacia abajo.", "Continúa levantando hasta que el brazo quede paralelo al suelo.", "Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Elevación Lateral a 1 Brazo en Polea', 'cable-one-arm-lateral-raise.gif', 'shoulders', '["Stand with your feet shoulder-width apart, facing the cable machine.", "Hold the cable handle with one hand, palm facing down, and stand far enough away from the machine so that there is tension on the cable.", "Keep your arm straight and slowly raise it out to the side until it is parallel to the ground.", "Pause for a moment at the top, then slowly lower your arm back down to the starting position.", "Repeat for the desired number of repetitions, then switch sides."]', '["Ponte de pie con los pies separados a la altura de los hombros, frente a la máquina de cable.", "Sujeta la agarradera del cable con una mano, con la palma hacia abajo, y colócate lo suficientemente alejado de la máquina para que haya tensión en el cable.", "Mantén el brazo recto y levántalo lentamente hacia el lado hasta que quede paralelo al suelo.", "Haz una pausa breve en la parte más alta, luego baja lentamente el brazo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Elevación Lateral a 1 Brazo Tumbado de Lado', 'dumbbell-side-lying-one-hand-raise.gif', 'shoulders', '["Lie on your side with your legs extended and your head supported by your arm.", "Hold a dumbbell in your top hand with your palm facing down.", "Keeping your arm straight, raise the dumbbell up to shoulder height.", "Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.", "Repeat for the desired number of repetitions, then switch sides."]', '["Túmbate de lado con las piernas extendidas y la cabeza apoyada sobre el brazo.", "Sujeta una mancuerna con la mano de arriba, con la palma hacia abajo.", "Manteniendo el brazo recto, sube la mancuerna hasta la altura del hombro.", "Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Elevación Lateral a Frontal con Mancuernas', 'dumbbell-lateral-to-front-raise.gif', 'shoulders', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.", "Keep your back straight and engage your core.", "Raise your arms out to the sides until they are parallel to the ground, keeping a slight bend in your elbows.", "Pause for a moment at the top, then slowly lower your arms back down to the starting position.", "Next, raise your arms in front of you until they are parallel to the ground, again keeping a slight bend in your elbows.", "Pause for a moment at the top, then slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia el cuerpo.", "Mantén la espalda recta y activa el core.", "Levanta los brazos hacia los lados hasta que queden paralelos al suelo, manteniendo una ligera flexión en los codos.", "Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.", "Luego, levanta los brazos frente a ti hasta que queden paralelos al suelo, manteniendo nuevamente una ligera flexión en los codos.", "Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación Lateral con Landmine', 'landmine-lateral-raise.gif', 'shoulders', '["Stand with your feet shoulder-width apart and knees slightly bent.", "Hold the barbell with an overhand grip, resting it on the front of your shoulders.", "Keeping your core engaged and back straight, lift the barbell up and away from your body, raising it to shoulder height.", "Pause for a moment at the top, then slowly lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.", "Sujeta la barra con un agarre prono, apoyándola en la parte delantera de los hombros.", "Manteniendo el core activado y la espalda recta, levanta la barra alejándola del cuerpo, elevándola hasta la altura del hombro.", "Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación Lateral en Máquina', 'lever-lateral-raise.gif', 'shoulders', '["Adjust the seat height and position yourself on the machine with your back against the pad.", "Grasp the handles with an overhand grip and keep your arms straight.", "Exhale and raise your arms out to the sides until they are parallel to the floor.", "Pause for a moment at the top, then inhale and slowly lower your arms back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en la almohadilla.", "Sujeta las asas con un agarre prono y mantén los brazos rectos.", "Exhala y levanta los brazos hacia los lados hasta que queden paralelos al suelo.", "Haz una pausa breve en lo alto, luego inhala y baja lentamente los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación Lateral Full Can con Mancuernas', 'dumbbell-full-can-lateral-raise.gif', 'shoulders', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.", "Keep your back straight and engage your core.", "Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the ground.", "Pause for a moment at the top, then slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia el cuerpo.", "Mantén la espalda recta y activa el core.", "Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo.", "Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación Lateral Sentado con Brazos Flexionados', 'dumbbell-seated-bent-arm-lateral-raise.gif', 'shoulders', '["Sit on a bench with your back straight and feet flat on the ground.", "Hold a dumbbell in each hand with your palms facing your body and your arms bent at a 90-degree angle.", "Keeping your elbows bent, raise your arms out to the sides until they are parallel to the ground.", "Pause for a moment at the top, then slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.", "Sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo y los brazos flexionados en un ángulo de 90 grados.", "Manteniendo los codos flexionados, levanta los brazos hacia los lados hasta que queden paralelos al suelo.", "Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación Lateral Sentado con Mancuernas', 'dumbbell-seated-lateral-raise.gif', 'shoulders', '["Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs.", "Keep your back straight and core engaged.", "Raise the dumbbells to your sides with a slight bend in your elbows, until your arms are parallel to the ground.", "Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco con los pies apoyados en el suelo y una mancuerna en cada mano, apoyadas sobre los muslos.", "Mantén la espalda recta y el core activado.", "Levanta las mancuernas hacia los lados con una ligera flexión en los codos, hasta que tus brazos queden paralelos al suelo.", "Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación Posterior a 1 Brazo Boca Abajo con Mancuerna', 'dumbbell-lying-one-arm-rear-lateral-raise.gif', 'shoulders', '["Lie face down on a flat bench with a dumbbell in one hand, hanging towards the floor.", "Keep your arm straight and lift the dumbbell out to the side, away from your body.", "Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."]', '["Túmbate boca abajo en un banco plano con una mancuerna en una mano, colgando hacia el suelo.", "Mantén el brazo recto y levanta la mancuerna hacia el lado, alejándola del cuerpo.", "Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia al otro brazo."]'),
  ('Elevación Posterior a 1 Brazo Tumbado de Lado con Mancuerna', 'dumbbell-lying-one-arm-deltoid-rear.gif', 'shoulders', '["Lie face down on a flat bench with a dumbbell in one hand, palm facing inwards.", "Extend your arm straight down towards the floor, keeping it close to your body.", "Raise your arm up and back, squeezing your shoulder blade towards your spine.", "Pause for a moment at the top, then slowly lower your arm back down to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Túmbate boca abajo en un banco plano con una mancuerna en una mano, con la palma hacia adentro.", "Extiende el brazo recto hacia el suelo, manteniéndolo cerca del cuerpo.", "Levanta el brazo hacia arriba y hacia atrás, acercando el omóplato hacia la columna.", "Haz una pausa breve en la parte más alta, luego baja lentamente el brazo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Elevación Posterior Boca Abajo con Mancuernas', 'dumbbell-lying-rear-lateral-raise.gif', 'shoulders', '["Lie face down on a flat bench with a dumbbell in each hand, palms facing each other.", "Extend your arms straight down towards the floor, keeping a slight bend in your elbows.", "Engaging your shoulder muscles, lift your arms out to the sides until they are parallel to the floor.", "Pause for a moment at the top, then slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca abajo en un banco plano con una mancuerna en cada mano, con las palmas enfrentadas entre sí.", "Extiende los brazos rectos hacia el suelo, manteniendo una ligera flexión en los codos.", "Activando los músculos de los hombros, levanta los brazos hacia los lados hasta que queden paralelos al suelo.", "Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación Posterior con Mancuernas en Banco Inclinado', 'dumbbell-incline-rear-lateral-raise-0326.gif', 'shoulders', '["Set up an incline bench at a 45-degree angle.", "Sit on the bench with your chest against the backrest and hold a dumbbell in each hand.", "Extend your arms straight down with your palms facing each other.", "Keeping a slight bend in your elbows, raise your arms out to the sides until they are parallel to the ground.", "Pause for a moment at the top, then slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Coloca un banco inclinado a un ángulo de 45 grados.", "Siéntate en el banco con el pecho contra el respaldo y sostén una mancuerna en cada mano.", "Extiende los brazos rectos hacia abajo con las palmas enfrentadas entre sí.", "Manteniendo una ligera flexión en los codos, levanta los brazos hacia los lados hasta que queden paralelos al suelo.", "Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación Posterior con Mancuernas y Apoyo de Cabeza', 'dumbbell-rear-lateral-raise-support-head.gif', 'shoulders', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the ground.", "Pause for a moment at the top, then slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano.", "Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.", "Levanta los brazos hacia los lados, manteniendo una ligera flexión en los codos, hasta que queden paralelos al suelo.", "Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación Posterior Sentado en Polea', 'cable-seated-rear-lateral-raise.gif', 'shoulders', '["Sit on a bench facing the cable machine with your feet flat on the ground.", "Grasp the cable handles with an overhand grip and extend your arms straight in front of you.", "Keeping your arms straight, slowly raise them out to the sides until they are parallel to the floor.", "Pause for a moment at the top, then slowly lower your arms back to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco frente a la máquina de cable con los pies apoyados planos en el suelo.", "Sujeta las agarraderas del cable con un agarre prono y extiende los brazos rectos frente a ti.", "Manteniendo los brazos rectos, levántalos lentamente hacia los lados hasta que queden paralelos al suelo.", "Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación Posterior Tumbado de Lado en el Suelo con Mancuerna', 'dumbbell-lying-on-floor-rear-delt-raise.gif', 'shoulders', '["Lie face down on the floor with a dumbbell in each hand, palms facing each other.", "Extend your arms straight out in front of you, keeping a slight bend in your elbows.", "Engaging your shoulder muscles, lift your arms up and out to the sides, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower your arms back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca abajo en el suelo con una mancuerna en cada mano, con las palmas enfrentadas entre sí.", "Extiende los brazos rectos frente a ti, manteniendo una ligera flexión en los codos.", "Activando los músculos de los hombros, levanta los brazos hacia arriba y hacia los lados, juntando los omóplatos.", "Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación Prona con Mancuernas en Banco Inclinado', 'dumbbell-incline-raise.gif', 'shoulders', '["Sit on an incline bench with a dumbbell in each hand, resting on your thighs.", "Lean back on the bench and raise the dumbbells to shoulder height, palms facing forward.", "Keeping your back against the bench, exhale and raise the dumbbells above your head, fully extending your arms.", "Pause for a moment at the top, then inhale and slowly lower the dumbbells back to shoulder height.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco inclinado con una mancuerna en cada mano, apoyadas sobre los muslos.", "Recuéstate en el banco y levanta las mancuernas hasta la altura de los hombros, con las palmas hacia adelante.", "Manteniendo la espalda contra el banco, exhala y levanta las mancuernas por encima de la cabeza, extendiendo completamente los brazos.", "Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la altura de los hombros.", "Repite el número de repeticiones deseado."]'),
  ('Esquiador con Barra', 'barbell-skier.gif', 'shoulders', '["Stand with your feet shoulder-width apart and hold a barbell in front of your thighs with an overhand grip.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.", "Simultaneously lift the barbell up towards your shoulders while jumping slightly off the ground.", "As you reach the top of the movement, quickly reverse the motion and lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra frente a los muslos con un agarre pronado.", "Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado.", "Levanta simultáneamente la barra hacia los hombros mientras saltas ligeramente del suelo.", "Al llegar a la parte más alta del movimiento, invierte rápidamente el movimiento y baja la barra de nuevo a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Estiramiento de Deltoides Posterior', 'rear-deltoid-stretch.gif', 'shoulders', '["Stand tall with your feet shoulder-width apart.", "Extend your right arm across your chest, placing your left hand on your right elbow.", "Gently pull your right arm towards your left shoulder, feeling a stretch in your right shoulder.", "Hold the stretch for 15-30 seconds, then release.", "Repeat on the other side."]', '["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.", "Extiende el brazo derecho a través del pecho, colocando la mano izquierda sobre el codo derecho.", "Tira suavemente del brazo derecho hacia el hombro izquierdo, sintiendo un estiramiento en el hombro derecho.", "Mantén el estiramiento durante 15-30 segundos, luego suelta.", "Repite del otro lado."]'),
  ('Gancho de Izquierda (Boxeo)', 'left-hook-boxing.gif', 'shoulders', '["Stand with your feet shoulder-width apart and your knees slightly bent.", "Keep your left hand up to protect your face and your right hand by your chin.", "Rotate your hips and pivot on your left foot as you extend your left arm forward in a punching motion.", "Twist your torso and engage your core muscles to generate power in the punch.", "Snap your arm back to the starting position and repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.", "Mantén la mano izquierda arriba para proteger el rostro y la mano derecha junto a la barbilla.", "Rota las caderas y pívota sobre el pie izquierdo mientras extiendes el brazo izquierdo hacia adelante con un movimiento de golpe.", "Gira el torso y activa los músculos del core para generar potencia en el golpe.", "Lleva el brazo rápidamente de vuelta a la posición inicial y repite el número de repeticiones deseado."]'),
  ('Jerk a 1 Brazo con Kettlebell', 'kettlebell-one-arm-jerk.gif', 'shoulders', '["Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder height.", "Bend your knees slightly and engage your core.", "Press the kettlebell overhead in a straight line, fully extending your arm.", "As you press the kettlebell overhead, simultaneously dip your knees and quickly straighten them to generate momentum.", "As the kettlebell reaches its highest point, quickly drop underneath it by bending your knees and hips.", "Catch the kettlebell with a slight bend in your knees and hips, and your arm fully extended overhead.", "Stand up straight, fully extending your knees and hips, and stabilize the kettlebell overhead.", "Lower the kettlebell back to the starting position by bending your knees and hips, and repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano a la altura del hombro.", "Flexiona ligeramente las rodillas y activa el core.", "Presiona la pesa rusa por encima de la cabeza en línea recta, extendiendo el brazo por completo.", "Mientras presionas la pesa rusa por encima de la cabeza, flexiona las rodillas simultáneamente y estíralas rápidamente para generar impulso.", "Cuando la pesa rusa llegue a su punto más alto, baja rápidamente por debajo de ella flexionando las rodillas y las caderas.", "Atrapa la pesa rusa con una ligera flexión de rodillas y caderas, y el brazo completamente extendido por encima de la cabeza.", "Ponte de pie recto, extendiendo por completo las rodillas y las caderas, y estabiliza la pesa rusa por encima de la cabeza.", "Baja la pesa rusa de vuelta a la posición inicial flexionando las rodillas y las caderas, y repite el número de repeticiones deseado."]'),
  ('Jerk Doble con Kettlebells', 'kettlebell-double-jerk.gif', 'shoulders', '["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.", "Bend your knees slightly and engage your core.", "Press the kettlebells overhead, fully extending your arms.", "Bend your knees and quickly drop into a partial squat.", "Explosively extend your hips and knees, driving the kettlebells overhead.", "Lock out your arms and catch the kettlebells overhead with your knees slightly bent.", "Stand up straight and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano a la altura de los hombros.", "Flexiona ligeramente las rodillas y activa el core.", "Presiona las pesas rusas por encima de la cabeza, extendiendo los brazos por completo.", "Flexiona las rodillas y baja rápidamente a una sentadilla parcial.", "Extiende explosivamente las caderas y las rodillas, impulsando las pesas rusas hacia arriba.", "Bloquea los brazos y atrapa las pesas rusas por encima de la cabeza con las rodillas ligeramente flexionadas.", "Ponte de pie recto y vuelve a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Paseo a 1 Brazo con Mancuerna por Encima de la Cabeza', 'dumbbell-single-arm-overhead-carry-3548.gif', 'shoulders', '["Stand tall with your feet shoulder-width apart, holding a dumbbell in one hand.", "Raise the dumbbell overhead, fully extending your arm.", "Engage your core and keep your back straight as you walk forward, maintaining the dumbbell overhead.", "Continue walking for the desired distance or time.", "Switch hands and repeat the exercise."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna con una mano.", "Levanta la mancuerna por encima de la cabeza, extendiendo completamente el brazo.", "Activa el core y mantén la espalda recta mientras caminas hacia adelante, sosteniendo la mancuerna por encima de la cabeza.", "Continúa caminando durante la distancia o el tiempo deseado.", "Cambia de mano y repite el ejercicio."]'),
  ('Paso de Rodillas con Balanceo con Peso', 'weighted-kneeling-step-with-swing.gif', 'shoulders', '["Start in a kneeling position with your knees hip-width apart and your back straight.", "Hold a weight in each hand, with your arms extended straight down in front of you.", "Engage your core and swing the weights up and overhead, keeping your arms straight.", "Lower the weights back down to the starting position and repeat for the desired number of repetitions."]', '["Comienza en posición de rodillas con las rodillas separadas a la altura de las caderas y la espalda recta.", "Sostén un peso en cada mano, con los brazos extendidos rectos hacia abajo frente a ti.", "Activa el core y balancea los pesos hacia arriba y por encima de la cabeza, manteniendo los brazos rectos.", "Baja los pesos de nuevo a la posición inicial y repite el número de repeticiones deseado."]'),
  ('Pirata con Kettlebell', 'kettlebell-pirate-supper-legs.gif', 'shoulders', '["Stand with your feet shoulder-width apart, holding a kettlebell in one hand.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Raise the kettlebell up to shoulder height, keeping your elbow close to your body.", "Extend your arm fully overhead, straightening your elbow.", "Lower the kettlebell back down to shoulder height, then return to the starting position.", "Repeat for the desired number of repetitions, then switch sides."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano.", "Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.", "Levanta la pesa rusa hasta la altura del hombro, manteniendo el codo cerca del cuerpo.", "Extiende el brazo por completo por encima de la cabeza, enderezando el codo.", "Baja la pesa rusa de vuelta a la altura del hombro, luego vuelve a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Press Antigravedad con Barra Z', 'ez-barbell-anti-gravity-press.gif', 'shoulders', '["Start by standing with your feet shoulder-width apart and holding the ez barbell with an overhand grip.", "Raise the barbell to shoulder height, keeping your elbows slightly bent and your palms facing forward.", "Press the barbell overhead, extending your arms fully.", "Lower the barbell back to shoulder height and repeat for the desired number of repetitions."]', '["Comienza de pie con los pies separados a la altura de los hombros y sosteniendo la barra EZ con agarre prono.", "Eleva la barra hasta la altura de los hombros, manteniendo los codos ligeramente flexionados y las palmas hacia adelante.", "Empuja la barra por encima de la cabeza, extendiendo completamente los brazos.", "Baja la barra de vuelta a la altura de los hombros y repite el número de repeticiones deseado."]'),
  ('Press Arnold con Kettlebell', 'kettlebell-arnold-press.gif', 'shoulders', '["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height with your palms facing towards you.", "Engage your core and press the kettlebells overhead, rotating your palms to face forward as you extend your arms.", "Pause at the top of the movement, then slowly lower the kettlebells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano a la altura de los hombros con las palmas hacia ti.", "Activa el core y empuja las pesas rusas por encima de la cabeza, girando las palmas hacia adelante mientras extiendes los brazos.", "Haz una pausa en la parte superior del movimiento, luego baja lentamente las pesas rusas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Press Balancín con Kettlebells', 'kettlebell-seesaw-press.gif', 'shoulders', '["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.", "Press one kettlebell overhead while keeping the other kettlebell at shoulder height.", "Lower the pressed kettlebell back to shoulder height while simultaneously pressing the other kettlebell overhead.", "Continue alternating the pressing motion, creating a seesaw-like movement.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano a la altura de los hombros.", "Presiona una pesa rusa por encima de la cabeza mientras mantienes la otra pesa rusa a la altura del hombro.", "Baja la pesa rusa presionada de vuelta a la altura del hombro mientras presionas simultáneamente la otra pesa rusa por encima de la cabeza.", "Continúa alternando el movimiento de presión, creando un movimiento similar a un balancín.", "Repite el número de repeticiones deseado."]'),
  ('Press Bradford de Pie con Barra', 'barbell-standing-bradford-press.gif', 'shoulders', '["Stand with your feet shoulder-width apart and hold the barbell in front of your shoulders with an overhand grip.", "Press the barbell overhead, fully extending your arms.", "Lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra frente a los hombros con agarre prono.", "Empuja la barra por encima de la cabeza, extendiendo completamente los brazos.", "Baja la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Press Bradford Sentado con Barra', 'barbell-seated-bradford-rocky-press.gif', 'shoulders', '["Sit on a bench with your back straight and feet flat on the ground.", "Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.", "Lift the barbell to shoulder height, keeping your elbows slightly bent and pointing forward.", "Press the barbell overhead, fully extending your arms.", "Lower the barbell back to shoulder height and repeat for the desired number of repetitions."]', '["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.", "Sujeta la barra con un agarre pronado, un poco más ancho que la separación de los hombros.", "Levanta la barra hasta la altura de los hombros, manteniendo los codos ligeramente flexionados y apuntando hacia delante.", "Empuja la barra por encima de la cabeza, extendiendo completamente los brazos.", "Baja la barra de vuelta a la altura de los hombros y repite el número de repeticiones deseado."]'),
  ('Press Cubano con Mancuernas', 'dumbbell-cuban-press.gif', 'shoulders', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height with your palms facing down.", "Keeping your core engaged and your elbows slightly bent, press the dumbbells up and overhead until your arms are fully extended.", "Rotate your wrists so that your palms are facing forward.", "Slowly lower the dumbbells back to the starting position, rotating your wrists back to the starting position as you do so.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano a la altura de los hombros con las palmas hacia abajo.", "Manteniendo el core activado y los codos ligeramente flexionados, empuja las mancuernas hacia arriba por encima de la cabeza hasta que los brazos queden completamente extendidos.", "Gira las muñecas de modo que las palmas queden mirando hacia adelante.", "Baja lentamente las mancuernas a la posición inicial, girando las muñecas de vuelta a la posición inicial mientras lo haces.", "Repite el número de repeticiones deseado."]'),
  ('Press de Hombro a 1 Brazo con Landmine', 'lever-one-arm-shoulder-press.gif', 'shoulders', '["Adjust the seat height and position yourself on the machine with your back against the pad.", "Grasp the lever handle with one hand and position your elbow at a 90-degree angle.", "Press the lever upward until your arm is fully extended overhead.", "Pause for a moment at the top, then slowly lower the lever back down to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."]', '["Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en la almohadilla.", "Sujeta el asa de la palanca con una mano y coloca el codo en un ángulo de 90 grados.", "Presiona la palanca hacia arriba hasta que el brazo quede completamente extendido por encima de la cabeza.", "Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia al otro brazo."]'),
  ('Press de Hombro a 1 Brazo de Pie con Agarre Neutro', 'dumbbell-standing-one-arm-palm-in-press.gif', 'shoulders', '["Stand with your feet shoulder-width apart, holding a dumbbell in one hand at shoulder height with your palm facing inwards.", "Engage your core and keep your back straight.", "Press the dumbbell upwards until your arm is fully extended.", "Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna con una mano a la altura del hombro, con la palma hacia adentro.", "Activa el core y mantén la espalda recta.", "Empuja la mancuerna hacia arriba hasta que el brazo quede completamente extendido.", "Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia al otro brazo."]'),
  ('Press de Hombros Alterno con Kettlebells', 'kettlebell-alternating-press.gif', 'shoulders', '["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.", "Press one kettlebell overhead, fully extending your arm.", "Lower the kettlebell back to shoulder height.", "Repeat with the other arm.", "Continue alternating arms for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano a la altura de los hombros.", "Empuja una pesa rusa por encima de la cabeza, extendiendo el brazo por completo.", "Baja la pesa rusa de nuevo a la altura de los hombros.", "Repite con el otro brazo.", "Continúa alternando los brazos durante el número de repeticiones deseado."]'),
  ('Press de Hombros Alterno de Pie con Mancuernas', 'dumbbell-standing-alternate-overhead-press.gif', 'shoulders', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing forward.", "Press one dumbbell overhead, fully extending your arm.", "Lower the dumbbell back to shoulder level.", "Repeat with the other arm.", "Continue alternating arms for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano a la altura de los hombros, con las palmas hacia adelante.", "Presiona una mancuerna por encima de la cabeza, extendiendo completamente el brazo.", "Baja la mancuerna de vuelta a la altura de los hombros.", "Repite con el otro brazo.", "Continúa alternando los brazos durante el número de repeticiones deseado."]'),
  ('Press de Hombros Alterno en Polea', 'cable-alternate-shoulder-press.gif', 'shoulders', '["Stand with your feet shoulder-width apart and grasp the handles of the cable machine with an overhand grip.", "Position your hands at shoulder height, with your palms facing forward.", "Keep your core engaged and your back straight.", "Press one handle up and forward until your arm is fully extended.", "Pause for a moment at the top, then slowly lower the handle back to the starting position.", "Repeat with the other arm.", "Alternate between arms for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta las agarraderas de la máquina de cable con agarre prono.", "Coloca las manos a la altura de los hombros, con las palmas mirando hacia adelante.", "Mantén el core activado y la espalda recta.", "Empuja una agarradera hacia arriba y hacia adelante hasta que el brazo quede completamente extendido.", "Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera de vuelta a la posición inicial.", "Repite con el otro brazo.", "Alterna entre los brazos el número de repeticiones deseado."]'),
  ('Press de Hombros Alterno Sentado con Mancuernas', 'dumbbell-seated-alternate-press.gif', 'shoulders', '["Sit on a bench with a dumbbell in each hand, palms facing forward.", "Raise the dumbbells to shoulder height, with your elbows bent and palms facing forward.", "Press one dumbbell up overhead, fully extending your arm.", "Lower the dumbbell back down to shoulder height.", "Repeat with the other arm.", "Continue alternating arms for the desired number of repetitions."]', '["Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adelante.", "Sube las mancuernas hasta la altura de los hombros, con los codos flexionados y las palmas hacia adelante.", "Presiona una mancuerna hacia arriba, por encima de la cabeza, extendiendo completamente el brazo.", "Baja la mancuerna de vuelta a la altura de los hombros.", "Repite con el otro brazo.", "Continúa alternando los brazos durante el número de repeticiones deseado."]'),
  ('Press de Hombros con Banda Elástica', 'band-shoulder-press.gif', 'shoulders', '["Stand with your feet shoulder-width apart and place the band under your feet.", "Hold the band with your palms facing forward and raise your hands to shoulder height, elbows bent.", "Press the band overhead, fully extending your arms.", "Pause for a moment at the top, then slowly lower the band back to shoulder height.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y coloca la banda bajo los pies.", "Sostén la banda con las palmas hacia adelante y eleva las manos a la altura de los hombros, con los codos flexionados.", "Empuja la banda por encima de la cabeza, extendiendo completamente los brazos.", "Haz una pausa por un momento en la parte superior, luego baja lentamente la banda de vuelta a la altura de los hombros.", "Repite el número de repeticiones deseado."]'),
  ('Press de Hombros con Landmine', 'lever-shoulder-press.gif', 'shoulders', '["Adjust the seat height and position yourself on the machine with your back against the backrest.", "Grasp the handles with an overhand grip and position your hands at shoulder level.", "Push the handles upward until your arms are fully extended, but do not lock your elbows.", "Pause for a moment at the top, then slowly lower the handles back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en el respaldo.", "Agarra las asas con un agarre prono y coloca las manos a la altura de los hombros.", "Empuja las asas hacia arriba hasta que los brazos queden completamente extendidos, pero sin bloquear los codos.", "Haz una pausa breve en lo alto, luego baja lentamente las asas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Press de Hombros de Pie con Agarre Neutro', 'dumbbell-standing-palms-in-press.gif', 'shoulders', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing inwards.", "Keeping your core engaged and your back straight, press the dumbbells upwards until your arms are fully extended overhead.", "Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano a la altura de los hombros, con las palmas hacia adentro.", "Manteniendo el core activado y la espalda recta, presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza.", "Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Press de Hombros de Pie con Mancuernas', 'dumbbell-standing-overhead-press.gif', 'shoulders', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing forward.", "Press the dumbbells upward until your arms are fully extended overhead.", "Pause for a moment at the top, then slowly lower the dumbbells back down to shoulder level.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano a la altura de los hombros, con las palmas hacia adelante.", "Presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza.", "Haz una pausa por un momento en la parte superior, luego baja lentamente las mancuernas de vuelta a la altura de los hombros.", "Repite el número de repeticiones deseado."]'),
  ('Press de Hombros en Polea', 'cable-shoulder-press.gif', 'shoulders', '["Adjust the cable machine so that the handles are at shoulder height.", "Stand facing away from the machine with your feet shoulder-width apart.", "Grasp the handles with an overhand grip and bring them up to shoulder level, with your elbows bent and pointing outwards.", "Press the handles upwards until your arms are fully extended overhead.", "Pause for a moment at the top, then slowly lower the handles back down to shoulder level.", "Repeat for the desired number of repetitions."]', '["Ajusta la máquina de cable de modo que las agarraderas queden a la altura del hombro.", "Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros.", "Sujeta las agarraderas con un agarre prono y llévalas hasta la altura del hombro, con los codos flexionados y apuntando hacia afuera.", "Empuja las agarraderas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza.", "Haz una pausa por un momento en la parte alta y luego baja lentamente las agarraderas de vuelta a la altura del hombro.", "Repite el número de repeticiones deseado."]'),
  ('Press de Hombros Sentado con Banda Elástica', 'resistance-band-seated-shoulder-press.gif', 'shoulders', '["Sit on a chair or bench with your back straight and feet flat on the ground.", "Hold the resistance band with both hands, palms facing forward, and bring it up to shoulder level.", "Press the band overhead, extending your arms fully.", "Pause for a moment at the top, then slowly lower the band back down to shoulder level.", "Repeat for the desired number of repetitions."]', '["Siéntate en una silla o banco con la espalda recta y los pies apoyados en el suelo.", "Sostén la banda elástica con ambas manos, con las palmas hacia adelante, y elévala hasta la altura de los hombros.", "Empuja la banda por encima de la cabeza, extendiendo completamente los brazos.", "Haz una pausa por un momento en la parte alta y luego baja lentamente la banda hasta la altura de los hombros.", "Repite el número de repeticiones deseado."]'),
  ('Press de Hombros Sentado en Máquina Smith', 'smith-seated-shoulder-press.gif', 'shoulders', '["Adjust the seat height so that the handles are at shoulder level.", "Sit on the machine with your back against the pad and your feet flat on the floor.", "Grasp the handles with an overhand grip and lift them off the supports, extending your arms fully.", "Lower the handles down to shoulder level, keeping your elbows slightly bent.", "Press the handles up overhead until your arms are fully extended.", "Pause for a moment at the top, then slowly lower the handles back down to shoulder level.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura del asiento de modo que las asas queden a la altura de los hombros.", "Siéntate en la máquina con la espalda contra la almohadilla y los pies planos sobre el suelo.", "Sujeta las asas con un agarre prono y levántalas de los soportes, extendiendo los brazos por completo.", "Baja las asas hasta la altura de los hombros, manteniendo los codos ligeramente flexionados.", "Empuja las asas hacia arriba, por encima de la cabeza, hasta que los brazos queden completamente extendidos.", "Haz una pausa por un momento en la parte alta y luego baja lentamente las agarraderas de vuelta a la altura del hombro.", "Repite el número de repeticiones deseado."]'),
  ('Press en W con Mancuernas', 'dumbbell-w-press.gif', 'shoulders', '["Sit on a bench with a dumbbell in each hand, palms facing forward.", "Raise the dumbbells to shoulder height, elbows bent and palms facing forward.", "Press the dumbbells upward until your arms are fully extended overhead.", "Lower the dumbbells back to shoulder height.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adelante.", "Sube las mancuernas hasta la altura de los hombros, con los codos flexionados y las palmas hacia adelante.", "Presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza.", "Baja las mancuernas de vuelta a la altura de los hombros.", "Repite el número de repeticiones deseado."]'),
  ('Press Lateral Alterno con Mancuernas', 'dumbbell-alternate-side-press.gif', 'shoulders', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height.", "Press one dumbbell overhead while keeping the other dumbbell at shoulder height.", "Lower the pressed dumbbell back to shoulder height while pressing the other dumbbell overhead.", "Continue alternating sides for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano a la altura de los hombros.", "Empuja una mancuerna por encima de la cabeza mientras mantienes la otra mancuerna a la altura del hombro.", "Baja la mancuerna empujada de vuelta a la altura del hombro mientras empujas la otra mancuerna por encima de la cabeza.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Press Militar de Pie con 2 Kettlebells', 'kettlebell-two-arm-military-press.gif', 'shoulders', '["Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder level with your palms facing forward.", "Engage your core and press the kettlebells overhead, fully extending your arms.", "Pause for a moment at the top, then slowly lower the kettlebells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa en cada mano a la altura del hombro con las palmas hacia adelante.", "Activa el core y presiona las pesas rusas por encima de la cabeza, extendiendo los brazos por completo.", "Haz una pausa breve en lo alto, luego baja lentamente las pesas rusas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Press Militar de Pie con Agarre Abierto', 'barbell-standing-wide-military-press.gif', 'shoulders', '["Stand with your feet shoulder-width apart and hold the barbell with an overhand grip, slightly wider than shoulder-width.", "Lift the barbell to shoulder height, keeping your elbows slightly in front of the bar.", "Press the barbell overhead, extending your arms fully.", "Lower the barbell back to shoulder height and repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros.", "Levanta la barra hasta la altura de los hombros, manteniendo los codos ligeramente por delante de la barra.", "Empuja la barra por encima de la cabeza, extendiendo completamente los brazos.", "Baja la barra de vuelta a la altura de los hombros y repite el número de repeticiones deseado."]'),
  ('Press Militar de Pie en Máquina Smith', 'smith-standing-military-press.gif', 'shoulders', '["Stand with your feet shoulder-width apart and your knees slightly bent.", "Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.", "Lift the barbell off the rack and bring it down to shoulder level, with your palms facing forward.", "Press the barbell upward until your arms are fully extended overhead.", "Pause for a moment at the top, then slowly lower the barbell back down to shoulder level.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.", "Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.", "Levanta la barra del soporte y bájala hasta la altura de los hombros, con las palmas hacia delante.", "Empuja la barra hacia arriba hasta que tus brazos queden completamente extendidos por encima de la cabeza.", "Haz una pausa de un momento en la parte superior y luego baja lentamente la barra de nuevo hasta la altura de los hombros.", "Repite el número de repeticiones deseado."]'),
  ('Press Militar Lateral a 1 Brazo con Kettlebell', 'kettlebell-one-arm-military-press-to-the-side.gif', 'shoulders', '["Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder height.", "Engage your core and keep your back straight.", "Press the kettlebell overhead, extending your arm fully.", "Pause for a moment at the top, then slowly lower the kettlebell back to the starting position.", "Repeat for the desired number of repetitions, then switch sides."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano a la altura del hombro.", "Activa el core y mantén la espalda recta.", "Presiona la pesa rusa por encima de la cabeza, extendiendo el brazo por completo.", "Haz una pausa breve en lo alto, luego baja lentamente la pesa rusa de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Press Militar Sentado con 2 Kettlebells', 'kettlebell-seated-two-arm-military-press.gif', 'shoulders', '["Sit on a bench with your back straight and feet flat on the ground.", "Hold a kettlebell in each hand at shoulder level with your palms facing forward.", "Press the kettlebells overhead by extending your arms fully.", "Pause for a moment at the top, then slowly lower the kettlebells back to shoulder level.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.", "Sujeta una pesa rusa en cada mano a la altura del hombro con las palmas hacia adelante.", "Presiona las pesas rusas por encima de la cabeza extendiendo los brazos por completo.", "Haz una pausa breve en lo alto, luego baja lentamente las pesas rusas de vuelta a la altura del hombro.", "Repite el número de repeticiones deseado."]'),
  ('Press Militar Tras Nuca de Pie en Máquina Smith', 'smith-standing-behind-head-military-press.gif', 'shoulders', '["Adjust the seat height of the smith machine so that the bar is at shoulder level.", "Stand with your feet shoulder-width apart and your knees slightly bent.", "Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.", "Lift the bar off the rack and step back, maintaining a stable stance.", "Position the bar behind your head, resting on your upper traps.", "Keep your core engaged and your chest lifted throughout the exercise.", "Press the bar overhead by extending your arms, fully straightening them.", "Pause briefly at the top of the movement, then slowly lower the bar back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura del asiento de la máquina Smith de modo que la barra quede a la altura de los hombros.", "Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.", "Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros.", "Levanta la barra del soporte y da un paso atrás, manteniendo una postura estable.", "Coloca la barra detrás de la cabeza, apoyándola en la parte alta de los trapecios.", "Mantén el core activado y el pecho elevado durante todo el ejercicio.", "Empuja la barra por encima de la cabeza extendiendo los brazos, estirándolos por completo.", "Haz una breve pausa en la parte alta del movimiento, luego baja lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Press por Encima de la Cabeza con Giro con Banda Elástica', 'band-twisting-overhead-press.gif', 'shoulders', '["Stand with your feet shoulder-width apart and place the band under your feet.", "Hold the band handles at shoulder height with your palms facing forward.", "Engage your core and press the band overhead, fully extending your arms.", "As you press, twist your torso to one side, keeping your hips stable.", "Pause for a moment at the top, then return to the starting position.", "Repeat the press and twist on the opposite side.", "Continue alternating sides for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y coloca la banda bajo los pies.", "Sujeta las asas de la banda a la altura de los hombros con las palmas mirando hacia delante.", "Activa el core y empuja la banda por encima de la cabeza, extendiendo completamente los brazos.", "Mientras empujas, gira el torso hacia un lado, manteniendo las caderas estables.", "Haz una pausa breve en la parte alta y luego vuelve a la posición inicial.", "Repite el empuje y el giro hacia el lado opuesto.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Press Scott con Mancuernas', 'dumbbell-scott-press.gif', 'shoulders', '["Sit on a bench with a dumbbell in each hand, palms facing forward.", "Raise the dumbbells to shoulder height, with your elbows bent and palms facing forward.", "Press the dumbbells upward until your arms are fully extended.", "Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adelante.", "Sube las mancuernas hasta la altura de los hombros, con los codos flexionados y las palmas hacia adelante.", "Empuja las mancuernas hacia arriba hasta que los brazos estén completamente extendidos.", "Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Press Sentado en el Suelo con Kettlebell', 'kettlebell-seated-press.gif', 'shoulders', '["Sit on a bench with your back straight and feet flat on the ground.", "Hold a kettlebell in each hand at shoulder height, palms facing forward.", "Press the kettlebells overhead, fully extending your arms.", "Lower the kettlebells back to shoulder height.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.", "Sujeta una pesa rusa en cada mano a la altura del hombro, con las palmas hacia adelante.", "Presiona las pesas rusas por encima de la cabeza, extendiendo los brazos por completo.", "Baja las pesas rusas de vuelta a la altura del hombro.", "Repite el número de repeticiones deseado."]'),
  ('Press Tras Nuca de Pie con Barra', 'standing-behind-neck-press.gif', 'shoulders', '["Stand with your feet shoulder-width apart and hold the barbell behind your neck with an overhand grip.", "Keep your back straight and core engaged.", "Press the barbell overhead by extending your arms, fully extending your elbows.", "Pause for a moment at the top, then slowly lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sostén la barra detrás del cuello con un agarre prono.", "Mantén la espalda recta y el core activado.", "Empuja la barra por encima de la cabeza extendiendo los brazos, estirando completamente los codos.", "Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Press Tras Nuca Sentado en Máquina Smith', 'smith-behind-neck-press.gif', 'shoulders', '["Adjust the seat height of the smith machine so that the bar is at shoulder level.", "Stand with your feet shoulder-width apart and your knees slightly bent.", "Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.", "Lift the bar off the rack and step back, maintaining a stable stance.", "Lower the bar down to the back of your neck, keeping your elbows pointing forward.", "Press the bar up overhead until your arms are fully extended.", "Pause for a moment at the top, then slowly lower the bar back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura del asiento de la máquina Smith de modo que la barra quede a la altura de los hombros.", "Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.", "Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros.", "Levanta la barra del soporte y da un paso atrás, manteniendo una postura estable.", "Baja la barra hacia la parte de atrás del cuello, manteniendo los codos apuntando hacia delante.", "Empuja la barra hacia arriba, por encima de la cabeza, hasta que los brazos queden completamente extendidos.", "Haz una pausa por un momento en la posición alta, luego baja lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Push Press a 1 Brazo con Kettlebell', 'kettlebell-one-arm-push-press.gif', 'shoulders', '["Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder level.", "Bend your knees slightly and engage your core.", "Press the kettlebell overhead by extending your arm and fully extending your legs.", "Lower the kettlebell back to the starting position by bending your knees and bringing the kettlebell back to your shoulder.", "Repeat for the desired number of repetitions, then switch sides."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano a la altura del hombro.", "Flexiona ligeramente las rodillas y activa el core.", "Presiona la pesa rusa por encima de la cabeza extendiendo el brazo y estirando por completo las piernas.", "Baja la pesa rusa de vuelta a la posición inicial flexionando las rodillas y devolviendo la pesa rusa al hombro.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Push Press con Mancuernas', 'dumbbell-push-press.gif', 'shoulders', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level.", "Bend your knees slightly and dip your body down, then explosively extend your legs and press the dumbbells overhead.", "Lock out your arms at the top of the movement, then lower the dumbbells back to shoulder level.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano a la altura de los hombros.", "Flexiona ligeramente las rodillas y baja el cuerpo, luego extiende las piernas de forma explosiva y presiona las mancuernas por encima de la cabeza.", "Bloquea los brazos en la parte superior del movimiento, luego baja las mancuernas de vuelta a la altura de los hombros.", "Repite el número de repeticiones deseado."]'),
  ('Push Press Doble con Kettlebells', 'kettlebell-double-push-press.gif', 'shoulders', '["Start by standing with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.", "Bend your knees slightly and engage your core.", "Initiate the movement by explosively extending your hips, knees, and ankles, driving the kettlebells overhead.", "As the kettlebells reach the top, press them fully overhead, locking out your arms.", "Lower the kettlebells back to the starting position by bending your elbows and bringing them back down to shoulder height.", "Repeat for the desired number of repetitions."]', '["Comienza de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa en cada mano a la altura del hombro.", "Flexiona ligeramente las rodillas y activa el core.", "Inicia el movimiento extendiendo explosivamente las caderas, las rodillas y los tobillos, impulsando las pesas rusas por encima de la cabeza.", "Cuando las pesas rusas lleguen arriba, presiónalas completamente por encima de la cabeza, bloqueando los brazos.", "Baja las pesas rusas a la posición inicial flexionando los codos y llevándolas de vuelta a la altura del hombro.", "Repite el número de repeticiones deseado."]'),
  ('Remo al Mentón a 1 Brazo con Mancuerna', 'dumbbell-one-arm-upright-row.gif', 'shoulders', '["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with an overhand grip.", "Let the dumbbell hang at arm''s length in front of your thighs, with your palm facing your body.", "Keeping your back straight and your core engaged, exhale and lift the dumbbell straight up towards your chin, leading with your elbow.", "Pause for a moment at the top, then inhale and slowly lower the dumbbell back down to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."]', '["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en una mano con agarre prono.", "Deja que la mancuerna cuelgue a la distancia de un brazo frente a los muslos, con la palma hacia el cuerpo.", "Manteniendo la espalda recta y el core activado, exhala y levanta la mancuerna recta hacia la barbilla, guiando con el codo.", "Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia al otro brazo."]'),
  ('Remo al Mentón Abierto con Mancuernas', 'dumbbell-raise.gif', 'shoulders', '["Stand holding a dumbbell in each hand in front of your thighs.", "Hold the dumbbells slightly apart and keep your back straight.", "Raise the dumbbells, driving your elbows out and up to shoulder height.", "Pause briefly, then lower slowly.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con una mancuerna en cada mano delante de los muslos.", "Separa un poco las mancuernas y mantén la espalda recta.", "Sube las mancuernas llevando los codos hacia fuera y hacia arriba, hasta la altura de los hombros.", "Haz una breve pausa y baja lentamente.", "Repite el número de repeticiones deseado."]'),
  ('Remo al Mentón con Mancuernas', 'dumbbell-upright-row.gif', 'shoulders', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.", "Let the dumbbells hang in front of your thighs, with your arms fully extended.", "Keeping your back straight and your core engaged, exhale and lift the dumbbells straight up towards your chin, leading with your elbows.", "Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono.", "Deja que las mancuernas cuelguen frente a tus muslos, con los brazos completamente extendidos.", "Manteniendo la espalda recta y el core activado, exhala y levanta las mancuernas rectas hacia tu barbilla, guiando el movimiento con los codos.", "Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo al Mentón en Máquina Smith', 'smith-upright-row.gif', 'shoulders', '["Stand with your feet shoulder-width apart, facing the smith machine.", "Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.", "Keep your back straight and your core engaged.", "Pull the barbell up towards your chin, leading with your elbows.", "Pause for a moment at the top, then slowly lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, de frente a la máquina Smith.", "Agarra la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros.", "Mantén la espalda recta y el core activado.", "Tira de la barra hacia tu barbilla, guiando el movimiento con los codos.", "Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo al Mentón en Polea', 'cable-upright-row.gif', 'shoulders', '["Stand with your feet shoulder-width apart, knees slightly bent, and hold the cable attachment with an overhand grip.", "Keep your back straight and your core engaged throughout the exercise.", "Pull the cable attachment straight up towards your chin, leading with your elbows.", "Pause for a moment at the top, squeezing your shoulder blades together.", "Slowly lower the cable attachment back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta el accesorio del cable con un agarre prono.", "Mantén la espalda recta y el core activado durante todo el ejercicio.", "Tira del accesorio del cable directamente hacia arriba, hacia tu barbilla, guiando con los codos.", "Haz una pausa breve en la parte alta, apretando los omóplatos entre sí.", "Baja lentamente el accesorio del cable de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo de Deltoides Posterior con Barra', 'barbell-rear-delt-row.gif', 'shoulders', '["Stand with your feet shoulder-width apart and knees slightly bent.", "Hold a barbell with an overhand grip, hands slightly wider than shoulder-width apart.", "Bend forward at the hips, keeping your back straight and chest up.", "Pull the barbell towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.", "Sujeta una barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros.", "Inclínate hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado.", "Tira de la barra hacia el pecho, juntando los omóplatos.", "Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo de Deltoides Posterior con Mancuerna en Banco', 'dumbbell-rear-delt-row-shoulder.gif', 'shoulders', '["Stand with your feet shoulder-width apart and knees slightly bent.", "Hold a dumbbell in each hand with your palms facing your body.", "Bend forward at the waist, keeping your back straight and your core engaged.", "Extend your arms straight down towards the floor, with a slight bend in your elbows.", "Raise the dumbbells out to the sides, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.", "Sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo.", "Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el core activado.", "Extiende los brazos rectos hacia el suelo, con una ligera flexión en los codos.", "Levanta las mancuernas hacia los lados, apretando los omóplatos entre sí.", "Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo de Deltoides Posterior de Pie con Banda Elástica', 'band-standing-rear-delt-row.gif', 'shoulders', '["Stand with your feet shoulder-width apart and place the band under your feet.", "Hold the band handles with your palms facing each other and your arms extended in front of you.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Pull the band towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the top, then slowly release the tension and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y coloca la banda bajo los pies.", "Sostén las agarraderas de la banda con las palmas mirándose entre sí y los brazos extendidos frente a ti.", "Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.", "Tira de la banda hacia el pecho, juntando los omóplatos.", "Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión y regresa a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo de Deltoides Posterior de Rodillas en Polea con Cuerda', 'cable-kneeling-rear-delt-row-with-rope-male.gif', 'shoulders', '["Attach a rope handle to a low cable pulley and kneel down facing the machine.", "Grasp the rope with a neutral grip (palms facing each other) and extend your arms fully in front of you.", "Keeping your back straight and core engaged, pull the rope towards your body by retracting your shoulder blades.", "Squeeze your shoulder blades together at the end of the movement and hold for a brief pause.", "Slowly release the tension and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Sujeta una agarradera de cuerda a una polea baja y ponte de rodillas frente a la máquina.", "Sujeta la cuerda con un agarre neutro (las palmas una frente a la otra) y extiende los brazos completamente frente a ti.", "Manteniendo la espalda recta y el core activado, jala la cuerda hacia el cuerpo retrayendo los omóplatos.", "Aprieta los omóplatos al final del movimiento y mantén la posición por una breve pausa.", "Libera lentamente la tensión y vuelve a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo de Deltoides Posterior en Máquina Smith', 'smith-rear-delt-row.gif', 'shoulders', '["Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the ground.", "Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.", "Keep your back straight and your core engaged as you pull the handles towards your chest, squeezing your shoulder blades together.", "Pause for a moment at the top of the movement, then slowly release the handles back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura del asiento y colócate en la máquina con el pecho contra la almohadilla y los pies planos en el suelo.", "Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros.", "Mantén la espalda recta y el core activado mientras tiras de las asas hacia el pecho, juntando las escápulas.", "Haz una pausa por un momento en la parte alta del movimiento, luego suelta lentamente las asas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Remo de Deltoides Posterior Sentado en Polea', 'cable-rear-delt-row-stirrups.gif', 'shoulders', '["Attach a stirrup handle to a low cable pulley and stand facing the machine.", "Grasp the handle with your left hand and take a step back with your right foot, positioning your body at a slight angle.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged.", "With your left arm extended and your palm facing down, pull the handle towards your chest by retracting your shoulder blade.", "Pause for a moment at the top of the movement, squeezing your shoulder blade.", "Slowly release the handle back to the starting position and repeat for the desired number of repetitions.", "Switch sides and repeat the exercise with your right arm."]', '["Sujeta un asa de estribo a una polea de cable baja y ponte de pie frente a la máquina.", "Sujeta el asa con la mano izquierda y retrocede un paso con el pie derecho, colocando el cuerpo en un ligero ángulo.", "Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado.", "Con el brazo izquierdo extendido y la palma hacia abajo, jala el asa hacia el pecho retrayendo el omóplato.", "Haz una pausa por un momento en la parte más alta del movimiento, apretando el omóplato.", "Suelta lentamente el asa de vuelta a la posición inicial y repite el número de repeticiones deseado.", "Cambia de lado y repite el ejercicio con el brazo derecho."]'),
  ('Rotación Externa de Hombro de Pie con Mancuernas', 'dumbbell-upright-shoulder-external-rotation.gif', 'shoulders', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing your body.", "Raise your arms out to the sides until they are parallel to the ground, keeping your elbows slightly bent.", "Rotate your arms externally, bringing the dumbbells up towards your head while keeping your elbows in the same position.", "Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo.", "Levanta los brazos hacia los lados hasta que queden paralelos al suelo, manteniendo los codos ligeramente flexionados.", "Gira los brazos hacia afuera, llevando las mancuernas hacia la cabeza mientras mantienes los codos en la misma posición.", "Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Rotación Externa de Hombro de Pie en Polea', 'cable-standing-shoulder-external-rotation.gif', 'shoulders', '["Stand with your feet shoulder-width apart and your knees slightly bent.", "Hold the cable handle with your arm extended in front of you, parallel to the ground.", "Keep your elbow slightly bent and your shoulder blades pulled back.", "Slowly rotate your arm outward, away from your body, while keeping your elbow in the same position.", "Pause for a moment at the end of the movement, then slowly return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.", "Sujeta el mango del cable con el brazo extendido frente a ti, paralelo al suelo.", "Mantén el codo ligeramente flexionado y los omóplatos retraídos hacia atrás.", "Rota lentamente el brazo hacia afuera, alejándolo de tu cuerpo, manteniendo el codo en la misma posición.", "Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Rotación Externa de Hombro Tumbado con Mancuerna', 'dumbbell-lying-external-shoulder-rotation.gif', 'shoulders', '["Lie on your side on a flat bench with your upper arm against your side and your elbow bent 90 degrees.", "Hold a dumbbell in your hand with your palm facing down.", "Keeping your upper arm against your side, slowly rotate your forearm upward as far as possible.", "Pause for a moment at the top, then slowly lower your forearm back down to the starting position.", "Repeat for the desired number of repetitions, then switch sides."]', '["Túmbate de lado en un banco plano con el brazo superior contra el costado y el codo flexionado a 90 grados.", "Sostén una mancuerna en la mano con la palma hacia abajo.", "Manteniendo el brazo superior contra el costado, gira lentamente el antebrazo hacia arriba lo más posible.", "Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Rotación Interna de Hombro Sentado en Polea', 'cable-seated-shoulder-internal-rotation.gif', 'shoulders', '["Sit on a bench or chair facing the cable machine with your feet flat on the ground.", "Hold the cable handle with your arm extended straight out in front of you, parallel to the ground.", "Keep your elbow slightly bent and your shoulder blades pulled back and down.", "Slowly rotate your arm inward, bringing the cable handle towards the center of your body.", "Pause for a moment at the end of the movement, then slowly return to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Siéntate en un banco o silla frente a la máquina de cable con los pies apoyados planos en el suelo.", "Sujeta la agarradera del cable con el brazo extendido recto frente a ti, paralelo al suelo.", "Mantén el codo ligeramente flexionado y los omóplatos retraídos hacia atrás y hacia abajo.", "Rota lentamente el brazo hacia adentro, llevando la agarradera del cable hacia el centro del cuerpo.", "Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Thruster con Kettlebells', 'kettlebell-thruster.gif', 'shoulders', '["Start by standing with your feet shoulder-width apart, holding a kettlebell in front of your chest with both hands, palms facing each other.", "Lower into a squat position by bending your knees and pushing your hips back, keeping your chest up and your back straight.", "As you reach the bottom of the squat, explosively drive through your heels to stand up, simultaneously pressing the kettlebell overhead.", "Lock out your arms at the top of the movement, fully extending your elbows.", "Lower the kettlebell back to the starting position by reversing the movement, bending your elbows and lowering the weight back to your chest.", "Repeat for the desired number of repetitions."]', '["Comienza de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente al pecho con ambas manos, con las palmas una frente a la otra.", "Baja a una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás, manteniendo el pecho elevado y la espalda recta.", "Al llegar a la parte baja de la sentadilla, empuja explosivamente con los talones para ponerte de pie, presionando al mismo tiempo la pesa rusa por encima de la cabeza.", "Bloquea los brazos en la parte alta del movimiento, extendiendo los codos por completo.", "Baja la pesa rusa de vuelta a la posición inicial invirtiendo el movimiento, flexionando los codos y bajando el peso de vuelta al pecho.", "Repite el número de repeticiones deseado."]'),
  ('Vuelta al Mundo con Mancuernas', 'dumbbell-standing-around-world.gif', 'shoulders', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.", "Extend your arms straight out to the sides at shoulder height, palms facing down.", "Keeping your arms straight, slowly rotate your arms in a circular motion, bringing the dumbbells in front of your body and then overhead.", "Continue the circular motion, bringing the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano.", "Extiende los brazos rectos hacia los lados a la altura de los hombros, con las palmas hacia abajo.", "Manteniendo los brazos rectos, gira lentamente los brazos en un movimiento circular, llevando las mancuernas frente al cuerpo y luego por encima de la cabeza.", "Continúa el movimiento circular, bajando las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Body-Up (Extensión de Tríceps con Peso Corporal)', 'body-up.gif', 'upper arms', '["Start by placing your hands on a raised surface, such as a bench or parallel bars, with your palms facing down and fingers pointing forward.", "Extend your legs out in front of you, keeping your heels on the ground and your body straight.", "Lower your body by bending your elbows, keeping them close to your sides, until your upper arms are parallel to the ground.", "Pause for a moment, then push through your palms to straighten your arms and lift your body back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza colocando las manos sobre una superficie elevada, como un banco o unas barras paralelas, con las palmas hacia abajo y los dedos apuntando hacia adelante.", "Extiende las piernas frente a ti, manteniendo los talones en el suelo y el cuerpo recto.", "Baja el cuerpo flexionando los codos, manteniéndolos cerca del cuerpo, hasta que los brazos superiores queden paralelos al suelo.", "Haz una pausa breve, luego empuja con las palmas para extender los brazos y levantar el cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Cargada Colgante Alterna con 2 Kettlebells', 'kettlebell-double-alternating-hang-clean.gif', 'upper arms', '["Stand with your feet shoulder-width apart, holding a kettlebell in each hand with an overhand grip.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.", "Allow the kettlebells to hang straight down in front of your body.", "In one fluid motion, explosively extend your hips and knees while shrugging your shoulders.", "As the kettlebells rise, pull them up towards your shoulders, keeping your elbows high and out to the sides.", "Catch the kettlebells at shoulder height, with your palms facing inward and your elbows pointing forward.", "Lower the kettlebells back down to the starting position and repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una pesa rusa en cada mano con agarre prono.", "Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado.", "Deja que las pesas rusas cuelguen rectas frente a tu cuerpo.", "En un solo movimiento fluido, extiende explosivamente las caderas y las rodillas mientras encoges los hombros.", "Mientras las pesas rusas suben, tira de ellas hacia los hombros, manteniendo los codos altos y hacia los lados.", "Atrapa las pesas rusas a la altura del hombro, con las palmas hacia adentro y los codos apuntando hacia adelante.", "Baja las pesas rusas de vuelta a la posición inicial y repite el número de repeticiones deseado."]'),
  ('Cargada Invertida desde Colgado con Kettlebell (Bottoms Up)', 'kettlebell-bottoms-up-clean-from-the-hang-position.gif', 'upper arms', '["Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.", "Allow the kettlebell to hang down between your legs, with your arm fully extended.", "In one fluid motion, explosively extend your hips and knees while pulling the kettlebell up towards your shoulder.", "As the kettlebell reaches shoulder height, rotate your wrist so that the bottom of the kettlebell is facing up.", "Catch the kettlebell at shoulder height with your elbow bent and your palm facing up.", "Lower the kettlebell back down to the starting position by reversing the movement.", "Repeat for the desired number of repetitions, then switch sides."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa con una mano en agarre prono.", "Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado.", "Deja que la pesa rusa cuelgue entre tus piernas, con el brazo completamente extendido.", "En un solo movimiento fluido, extiende explosivamente las caderas y las rodillas mientras tiras de la pesa rusa hacia el hombro.", "Cuando la pesa rusa llegue a la altura del hombro, rota la muñeca de modo que la base de la pesa rusa quede hacia arriba.", "Atrapa la pesa rusa a la altura del hombro con el codo flexionado y la palma hacia arriba.", "Baja la pesa rusa de vuelta a la posición inicial invirtiendo el movimiento.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Curl a 1 Brazo de Pie sobre Banco Inclinado', 'dumbbell-standing-one-arm-curl-over-incline-bench.gif', 'upper arms', '["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing forward.", "Place your other hand on an incline bench for support.", "Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps.", "Pause for a moment at the top, then inhale and slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna con una mano, con la palma hacia adelante.", "Coloca la otra mano sobre un banco inclinado para apoyarte.", "Manteniendo fija la parte superior del brazo, exhala y flexiona la mancuerna hacia el hombro contrayendo el bíceps.", "Haz una pausa por un momento arriba, luego inhala y baja lentamente la mancuerna a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Curl Alto con Mancuernas (Doble Bíceps)', 'dumbbell-high-curl.gif', 'upper arms', '["Stand up straight with a dumbbell in each hand, palms facing forward.", "Keep your upper arms stationary and curl the dumbbells as high as possible while contracting your biceps.", "Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante.", "Mantén los brazos superiores quietos y flexiona las mancuernas lo más alto posible contrayendo los bíceps.", "Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl Araña con Barra Z', 'ez-barbell-spider-curl.gif', 'upper arms', '["Stand with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.", "Rest your upper arms on a preacher bench or stability ball, allowing your elbows to hang down.", "Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.", "Pause for a moment at the top, squeezing your biceps.", "Inhale and slowly lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, palmas hacia arriba.", "Apoya los brazos superiores en un banco scott o en un balón de estabilidad, dejando que los codos cuelguen hacia abajo.", "Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros.", "Haz una pausa breve en la parte alta, apretando los bíceps.", "Inhala y baja lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl Araña Inverso a 1 Brazo', 'dumbbell-one-arm-reverse-spider-curl.gif', 'upper arms', '["Stand up straight with a dumbbell in one hand, palm facing down and arm fully extended.", "Keeping your upper arm stationary, curl the dumbbell towards your shoulder by flexing your elbow.", "Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Ponte de pie con una mancuerna en una mano, con la palma hacia abajo y el brazo completamente extendido.", "Manteniendo el brazo superior quieto, flexiona la mancuerna hacia el hombro flexionando el codo.", "Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Curl Araña Inverso con Mancuernas', 'dumbbell-reverse-spider-curl.gif', 'upper arms', '["Stand up straight with a dumbbell in each hand, palms facing your body and arms fully extended.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con la espalda recta, con una mancuerna en cada mano, las palmas hacia tu cuerpo y los brazos completamente extendidos.", "Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.", "Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl Concentrado a 1 Brazo de Pie', 'dumbbell-standing-one-arm-concentration-curl.gif', 'upper arms', '["Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand, palm facing up.", "Place your free hand on your thigh for support.", "Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps.", "Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros, sujetando una mancuerna con una mano, con la palma hacia arriba.", "Coloca la mano libre sobre el muslo para apoyarte.", "Manteniendo fija la parte superior del brazo, exhala y flexiona la mancuerna hacia el hombro contrayendo el bíceps.", "Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Curl Concentrado con la Pierna', 'biceps-leg-concentration-curl.gif', 'upper arms', '["Sit on a bench with your legs spread apart and your feet flat on the ground.", "Hold a dumbbell in one hand and place your elbow on the inside of your thigh, just above the knee.", "With your palm facing up, curl the dumbbell towards your shoulder while keeping your upper arm stationary.", "Squeeze your biceps at the top of the movement, then slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Siéntate en un banco con las piernas separadas y los pies planos en el suelo.", "Sujeta una mancuerna con una mano y coloca el codo en la parte interna del muslo, justo por encima de la rodilla.", "Con la palma hacia arriba, flexiona la mancuerna hacia el hombro manteniendo el brazo superior quieto.", "Contrae el bíceps en la parte más alta del movimiento, luego baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Curl Concentrado con Mancuerna', 'dumbbell-concentration-curl.gif', 'upper arms', '["Sit on a bench with your legs spread apart and a dumbbell in one hand, resting your elbow on the inside of your thigh.", "Fully extend your arm and hold the dumbbell with an underhand grip.", "Keeping your upper arm stationary, exhale and curl the weight up towards your shoulder while contracting your biceps.", "Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Siéntate en un banco con las piernas separadas y una mancuerna en una mano, apoyando el codo en la parte interna del muslo.", "Extiende completamente el brazo y sujeta la mancuerna con un agarre supino.", "Manteniendo el brazo superior quieto, exhala y flexiona el peso hacia el hombro mientras contraes el bíceps.", "Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Curl Concentrado de Pie con Barra', 'barbell-standing-concentration-curl.gif', 'upper arms', '["Stand with your feet shoulder-width apart and hold a barbell in one hand, palm facing up.", "Rest your opposite hand on your thigh for support.", "Keeping your upper arm stationary, exhale and curl the weight up towards your shoulder.", "Pause for a moment at the top, squeezing your biceps.", "Inhale and slowly lower the weight back down to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con una mano, con la palma hacia arriba.", "Apoya la otra mano sobre el muslo para mayor estabilidad.", "Manteniendo el brazo superior quieto, exhala y flexiona el peso hacia el hombro.", "Haz una pausa breve en la parte alta, apretando los bíceps.", "Inhala y baja lentamente el peso de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Curl Concentrado de Pie con Mancuernas', 'dumbbell-standing-concentration-curl.gif', 'upper arms', '["Stand with your feet shoulder-width apart and hold a dumbbell in one hand, with your arm fully extended and palm facing inwards.", "Place your opposite hand on your thigh for support.", "Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder by contracting your biceps.", "Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna con una mano, con el brazo completamente extendido y la palma hacia adentro.", "Apoya la otra mano sobre el muslo para mayor estabilidad.", "Manteniendo fija la parte superior del brazo, exhala y flexiona la mancuerna hacia el hombro contrayendo el bíceps.", "Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]');
insert into public.exercises (name, video_url, body_part_id, instructions_en, instructions_es)
